/** Описание системы — docs/law.md. */
import type { Character } from '../entities/Character';
import type { EntityManager } from '../entities/EntityManager';
import type { GameMap, Poi } from '../world/GameMap';
import type { NavGrid } from '../world/NavGrid';
import type { EventBus } from '../core/EventBus';
import type { Rng } from '../core/rng';
import type { DoorSystem, DoorGroup } from './DoorSystem';
import { canSeeCircle } from '../world/visibility';
import { adjustLoyalty } from './Loyalty';
import { LOYALTY } from '../config/loyalty';
import { ERRANDS } from '../config/errands';
import { STAFFING } from '../config/staffing';
import { LAW, PASSPORT, VIOLATION_NAMES, type Violation, type WantedCharge } from '../config/law';
import { VISION } from '../config/vision';
import { loyalistPerk } from './Loyalty';
import { FACTIONS, cpHas } from '../config/factions';
import { LINES, fill } from '../config/lines';
import { phrase } from './phrases';
import { T } from '../world/tiles';
import { apparentFaction, coverAuthority } from '../entities/cover';
import { PrisonerBrain } from '../ai/brains/PrisonerBrain';
import { CHARACTER } from '../config/entities';
import { PARTISANS, UNDERGROUND } from '../config/underground';
import { SUSPECTS } from '../config/suspects';
import { ITEMS, type ItemId } from '../config/items';
import { foreignPassport } from './Passports';
import type { Vec2 } from '../core/math';

const PRISONER_MASS = 0.4;

export interface Verdict {
  kind: 'ok' | 'fine' | 'arrest';
  reason: Violation;
  fine: number;
}

export interface Cell {
  index: number;
  /** Центр камеры, px мира. */
  x: number;
  y: number;
  /** Точка в коридоре перед дверью, px мира. */
  frontX: number;
  frontY: number;
  door: DoorGroup | null;
  bounds: { x0: number; y0: number; x1: number; y1: number };
  /** Общая камера (много мест) — для граждан и партизан. */
  common: boolean;
  /** Места: у одиночной — одно в центре, у общей — по площади. */
  slots: CellSlot[];
  /** Камера тюрьмы Протектората: повстанцев держат бессрочно, пока не освободят свои. */
  prison: boolean;
  /** Дверь выбита спецагентом: до этого времени не запирается. */
  brokenUntil: number;
}

export interface CellSlot {
  x: number;
  y: number;
  occupant: Character | null;
  reserved: Character | null;
}

/** Партизан или спецагент (подполье). */
export function isUnderground(c: Character): boolean {
  return c.faction === 'rebel' && (c.profession === 'partisan' || c.profession === 'spec_agent');
}

/**
 * Кого ведут в тюрьму Протектората: всех повстанцев — армию, подполье, перебежчиков — и задержанных по делу
 * за убийство или нападение с оружием (причина ареста — в law.reason, её ставит arrest).
 */
export function belongsInPrison(c: Character): boolean {
  return c.faction === 'rebel' || c.law.reason === 'murder' || c.law.reason === 'assault' || (c.law.wanted && wantedLevel(c) >= 2);
}

/** Статья розыска (нет — «неподчинение») и её описание (LAW.wanted.charges). */
export function chargeOf(c: Character): WantedCharge {
  return c.law.wantedFor ?? 'flight';
}

export function chargeDef(c: Character): (typeof LAW.wanted.charges)[WantedCharge] {
  return LAW.wanted.charges[chargeOf(c)];
}

/** Степень розыска: 1 — мелкое, 2 — тяжкое, 3 — особо тяжкое. */
export function wantedLevel(c: Character): 1 | 2 | 3 {
  return chargeDef(c).level;
}

/** Изъятое при водворении в тюрьму: стволы, патроны, гранаты. */
function confiscable(id: ItemId): boolean {
  const k = ITEMS[id].kind;
  return k === 'weapon' || k === 'ammo' || id === 'grenade' || id === 'smoke_grenade' || id === 'fire_grenade';
}

/** Кого сажают в общую камеру: граждан, ТС и поднадзорных (не бойцов армии). */
function belongsInCommon(c: Character): boolean {
  return c.faction === 'citizen' || c.faction === 'cwu' || c.faction === 'vort';
}

/**
 * Закон Верхнеречье: кто что нарушил на глазах у ВС, приказы «стоять», проверка документов, штрафы,
 * аресты, камеры КПЗ и сроки. Решения за NPC (побежит ли) принимаются здесь.
 * Мозги ВС (CpBrain) решают, КОГДА вмешаться; эта система — ЧТО из этого следует.
 */
export class LawSystem {
  readonly cells: Cell[] = [];
  private time = 0;
  /** Комната изъятого тюрьмы: что забрали у каждого заключённого (отдают при освобождении своими). */
  readonly evidence = new Map<Character, { id: ItemId; qty: number }[]>();
  /** Выход из тюрьмы (за воротами двора) — туда выводят отсидевшего игрока. */
  prisonGate: Vec2 | null = null;
  /** Куда выводить отпущенного (из тюрьмы — за её ворота; иначе ворота Управы). */
  readonly releaseSpot = new Map<Character, Vec2>();
  /** Последний «засвет» разыскиваемого: от него идёт срок розыска (LAW.wanted). */
  private readonly wantedAt = new WeakMap<Character, number>();
  /** Когда человека последний раз оштрафовали за комендантский час в квартале (повторно — арест, LAW.zoneCurfewRepeat). */
  private readonly zoneCurfewFined = new WeakMap<Character, number>();
  /** Площади блок-постов на стене Верхнего города и когда кого там досматривали. */
  private borderAreas: readonly Poi[] | null = null;
  private readonly borderChecked = new WeakMap<Character, number>();

  constructor(
    private readonly map: GameMap,
    private readonly nav: NavGrid,
    private readonly doors: DoorSystem,
    private readonly entities: EntityManager,
    private readonly bus: EventBus,
    private readonly rng: Rng,
  ) {
    this.buildCells();
  }

  get now(): number {
    return this.time;
  }

  private buildCells(): void {
    const map = this.map;
    const ts = map.tileSize;
    const pois = [
      ...map.poisOf('cell').map((p) => ({ p, common: false, prison: false })),
      ...map.poisOf('common_cell').map((p) => ({ p, common: true, prison: false })),
      ...map.poisOf('prison_cell').map((p) => ({ p, common: false, prison: true })),
    ];
    pois.forEach(({ p: poi, common, prison }, index) => {
      // Камера — связная область пола в зоне КПЗ вокруг точки.
      const zone = map.zoneAtTile(poi.x, poi.y);
      let x0 = poi.x, y0 = poi.y, x1 = poi.x, y1 = poi.y;
      const seen = new Set<number>([poi.y * map.width + poi.x]);
      const stack = [[poi.x, poi.y]];
      while (stack.length) {
        const [x, y] = stack.pop()!;
        x0 = Math.min(x0, x); y0 = Math.min(y0, y); x1 = Math.max(x1, x); y1 = Math.max(y1, y);
        for (const [nx, ny] of [[x + 1, y], [x - 1, y], [x, y + 1], [x, y - 1]]) {
          const k = ny * map.width + nx;
          if (seen.has(k) || map.tileAt(nx, ny) !== T.INTERIOR || map.zoneAtTile(nx, ny) !== zone) continue;
          seen.add(k);
          stack.push([nx, ny]);
        }
      }
      let door: DoorGroup | null = null;
      for (let y = y0 - 1; y <= y1 + 1 && !door; y++) {
        for (let x = x0 - 1; x <= x1 + 1 && !door; x++) door = this.doors.groupAtTile(x, y);
      }
      const cx = ((x0 + x1 + 1) / 2) * ts;
      const cy = ((y0 + y1 + 1) / 2) * ts;
      let fx = cx;
      let fy = cy;
      if (door) {
        const dx = door.x - cx;
        const dy = door.y - cy;
        const d = Math.hypot(dx, dy) || 1;
        fx = door.x + (dx / d) * 36;
        fy = door.y + (dy / d) * 36;
      }
      const slots: CellSlot[] = [];
      if (common || prison) {
        // Места — центры якорей внутри камеры, не ближе spacing друг к другу и не у самой двери.
        const C = prison ? LAW.prison.cell : LAW.commonCell;
        const nav = this.nav;
        for (let ay = y0; ay < y1 && slots.length < C.max; ay++) {
          for (let ax = x0; ax < x1 && slots.length < C.max; ax++) {
            if (!nav.isWalkable(ax, ay)) continue;
            const x = (ax + 1) * ts;
            const y = (ay + 1) * ts;
            if (door && Math.hypot(door.x - x, door.y - y) < C.spacing * 1.5) continue;
            if (slots.some((s) => Math.hypot(s.x - x, s.y - y) < C.spacing)) continue;
            slots.push({ x, y, occupant: null, reserved: null });
          }
        }
      }
      if (!slots.length) slots.push({ x: cx, y: cy, occupant: null, reserved: null });
      // Дверь камеры тюрьмы — решётка: сквозь неё видно, кто сидит.
      if (prison && door) for (const t of door.tiles) map.grate[t] = 1;
      this.cells.push({ index, x: cx, y: cy, frontX: fx, frontY: fy, door, bounds: { x0, y0, x1, y1 }, common, slots, prison, brokenUntil: 0 });
    });
    this.prisonGate = this.findPrisonGate();
  }

  /**
   * Ворота тюрьмы: середина той стороны здания, к которой ближе двор, и на PRISON.gateOut тайлов наружу
   * (там начинается проезд к улице).
   */
  private findPrisonGate(): Vec2 | null {
    const p = this.map.poisOf('prison')[0];
    const yard = this.map.poisOf('prison_yard')[0];
    if (!p || !yard || p.w == null || p.h == null || yard.w == null || yard.h == null) return null;
    const ts = this.map.tileSize;
    const yx = yard.x + yard.w / 2;
    const yy = yard.y + yard.h / 2;
    const cx = p.x + p.w / 2;
    const cy = p.y + p.h / 2;
    const out = LAW.prison.gateOut;
    let gx = cx;
    let gy = cy;
    // Сторона со двором: смещение центра двора от центра здания — по большей оси.
    if (Math.abs(yx - cx) / p.w > Math.abs(yy - cy) / p.h) gx = yx > cx ? p.x + p.w + out : p.x - out;
    else gy = yy > cy ? p.y + p.h + out : p.y - out;
    const a = this.nav.nearestWalkable(gx * ts, gy * ts, 6);
    return a >= 0 ? { x: this.nav.worldX(a), y: this.nav.worldY(a) } : null;
  }

  /** Может ли observer увидеть target: дальность, угол обзора, стены и закрытые двери. */
  canSee(observer: Character, target: Character): boolean {
    const dx = target.x - observer.x;
    const dy = target.y - observer.y;
    const d = Math.hypot(dx, dy);
    if (d > VISION.npcRange) return false;
    if (d > VISION.npcCloseAwareness) {
      let a = Math.atan2(dy, dx) - observer.facing;
      while (a > Math.PI) a -= Math.PI * 2;
      while (a < -Math.PI) a += Math.PI * 2;
      if (Math.abs(a) > ((VISION.npcFovDeg / 2) * Math.PI) / 180) return false;
    }
    return canSeeCircle(this.map, observer.x, observer.y, target.x, target.y, target.radius);
  }

  /** Задаёт Game: нарушает ли персонаж комендантский час (красный код, на улице). */
  curfewCheck: (c: Character) => boolean = () => false;
  /** Задаёт Brawls: дерётся ли персонаж на кулаках (нарушение 'fight'). */
  fightCheck: (c: Character) => boolean = () => false;
  /** Задаёт Game: нашли свёрток при обыске (поручение сорвано). */
  onContraband: (c: Character) => void = () => {};
  /** Задаёт Game: паникует ли персонаж (бег от стрельбы — не нарушение). */
  panicking: (c: Character) => boolean = () => false;
  /** Заслуги юнита ВС (Staffing.merit). */
  merit: (c: Character, pts: number) => void = () => {};
  /** Без пропуска на режимном объекте (Access.trespassing) — нарушение «запретная зона». */
  trespass: (c: Character) => boolean = () => false;
  /** Задаёт Game: обвинение по делу (Suspects) — убийство или нападение с оружием, иначе null. */
  charge: (c: Character) => 'murder' | 'assault' | null = () => null;
  /** Задаёт Game: нарушает ли персонаж комендантский час в своём квартале (Escalation). */
  zoneCurfew: (c: Character) => boolean = () => false;
  /** Задаёт Game: дело по персонажу закрыто (задержан, водворён в камеру) — Suspects. */
  closeCase: (c: Character) => void = () => {};

  /** Подпольщик под личиной у люка в запретной зоне (UNDERGROUND.hatchShadow): его там не замечают. */
  private inHatchShadow(c: Character): boolean {
    if (c.faction !== 'rebel' || !c.disguised) return false;
    const r = UNDERGROUND.hatchShadow;
    return this.map.hatches.some((h) => Math.hypot(h.city.x - c.x, h.city.y - c.y) < r);
  }

  /** Нарушение, которое observer видит прямо сейчас, или null. */
  observe(observer: Character, target: Character): Violation | null {
    // Лежащего тяжелораненого не «замечают» как нарушителя: его задерживают отдельно (ai/Tactics).
    if (FACTIONS[target.faction].authority || target.law.phase !== 'none' || !target.alive || target.downed) return null;
    // Переодетый в сотрудника Протектората — «свой».
    if (coverAuthority(target)) return null;
    // Поднадзорных-рабов Протекторат не проверяет.
    if (target.faction === 'vort') return null;
    if (!this.canSee(observer, target)) return null;
    // Повстанца узнают сразу (форма), вооружённого — тоже; партизана в маскировке — нет.
    if (target.faction === 'rebel' && !target.disguised) return 'rebel';
    // Только что украл — на глазах у ВС.
    if ((target.law.crimeUntil ?? -1) > this.time) return 'theft';
    if ((target.law.riotUntil ?? -1) > this.time) return 'riot';
    if (target.weapon) return 'weapon';
    // Разыскиваемого узнают в лицо вблизи (ориентировка; чем тяжелее статья — тем дальше); в личине — нет.
    // Опознали — срок розыска заново.
    if (target.law.wanted && !target.disguised && Math.hypot(target.x - observer.x, target.y - observer.y) <= LAW.wanted.face[wantedLevel(target) - 1]) {
      this.wantedAt.set(target, this.time);
      return 'wanted';
    }
    if (this.fightCheck(target)) return 'fight';
    const zk = this.map.zoneAtWorld(target.x, target.y)?.kind;
    // В порт (зона ГЭС) докерам ТС — по работе.
    if (zk === 'restricted' && !this.inHatchShadow(target)) return 'restricted';
    if (zk === 'ges' && !(target.profession === 'packer' && apparentFaction(target) === 'cwu')) return 'restricted';
    // На склад Протектората посторонним нельзя (рабочие ТС — по работе).
    if (zk === 'arsenal' && apparentFaction(target) === 'citizen') return 'restricted';
    // В тюрьму посторонним нельзя никому.
    if (zk === 'prison' && target.law.phase === 'none') return 'restricted';
    // Режимный объект без пропуска (вошёл, пока вахты не было).
    if (this.trespass(target)) return 'restricted';
    if (this.curfewCheck(target)) return 'curfew';
    if (this.zoneCurfew(target)) return 'zone_curfew';
    // Лоялистам бегать разрешено.
    // Выпад и отброс в драке — не бег (Melee: impulse).
    if (target.moveSpeed > LAW.runSpeed && target.melee.impulse <= this.now && !this.panicking(target) && !loyalistPerk(target, 'run')) return 'running';
    return null;
  }

  /** Можно ли сейчас устроить плановую проверку. */
  checkable(target: Character): boolean {
    return (
      !FACTIONS[target.faction].authority && !coverAuthority(target) && target.faction !== 'vort' && target.law.phase === 'none' && target.alive && !target.downed &&
      this.time - target.law.lastCheck > LAW.recheckCooldown
    );
  }

  /** ВС приказывает стоять. NPC может решить бежать. */
  order(handler: Character, target: Character, reason: Violation): void {
    const law = target.law;
    law.phase = 'ordered';
    law.handler = handler;
    law.reason = reason;
    law.orderX = target.x;
    law.orderY = target.y;
    law.since = this.time;
    const lines =
      reason === 'running' ? LINES.cpOrderRun
      : reason === 'restricted' ? LINES.cpOrderRestricted
      : reason === 'curfew' ? LINES.cpOrderCurfew
      : reason === 'zone_curfew' ? LINES.cpOrderZoneCurfew
      : reason === 'suspect' ? LINES.cpOrderSuspect
      : reason === 'insult' ? LINES.cpOrderInsult
      : reason === 'rebel' || reason === 'weapon' ? LINES.cpOrderRebel
      : reason === 'wanted' ? LINES.cpOrderWanted
      : LINES.cpOrder;
    handler.say(phrase(this.rng, handler, lines, target), this.time);
    if (!target.isPlayer) {
      // Подпольщик под личиной не бежит: бег выдал бы его. Лоялист (не в розыске) — тоже: ему незачем.
      const loyal = target.faction === 'citizen' && target.loyalty >= LOYALTY.uniform.min && !law.wanted;
      // Бежит тот, кому есть что скрывать (под личиной — поддельный паспорт: «без документов» он не бежит).
      const guilty = !target.disguised && (law.wanted || !law.hasCid || (law.crimeUntil ?? -1) > this.time || (law.riotUntil ?? -1) > this.time || reason === 'weapon' || reason === 'rebel' || reason === 'theft');
      const table = guilty ? LAW.npc.fleeChance : LAW.npc.fleeCalm;
      const base = table[target.profession ?? ''] ?? table[target.faction] ?? 0.05;
      const flee = target.disguised || (loyal && !guilty) ? 0 : base * (target.loyalty < 0 ? LAW.npc.lowLoyaltyMul : 1);
      if (this.rng.chance(Math.min(1, flee))) this.startFlee(target);
      else target.say(phrase(this.rng, target, LINES.comply, handler), this.time, 2);
    }
  }

  startFlee(target: Character): void {
    const law = target.law;
    law.phase = 'fleeing';
    law.reason = 'resisting';
    law.since = this.time;
    target.say(phrase(this.rng, target, LINES.flee), this.time, 2);
    if (law.handler) {
      law.handler.say(phrase(this.rng, law.handler, LINES.cpChase), this.time);
      if (this.onFlee && !law.handler.isPlayer) this.onFlee(law.handler, target);
      else this.log(`${label(law.handler)}: убегает ${who(target, true).toLowerCase()}`, 'radio');
    }
  }

  /** Начать проверку (ВС рядом). */
  beginCheck(handler: Character, target: Character): void {
    const law = target.law;
    law.phase = 'checking';
    law.handler = handler;
    law.since = this.time;
    law.lastCheck = this.time;
    if (!law.reason) law.reason = 'routine';
  }

  /** Решение по результатам проверки документов. */
  /** Стоит на площади блок-поста на стене Верхнего города (там досматривают). */
  atBorder(c: Character): boolean {
    this.borderAreas ??= this.map.poisOf('border_check');
    const ts = this.map.tileSize;
    const tx = c.x / ts;
    const ty = c.y / ts;
    return this.borderAreas.some((p) => tx >= p.x && ty >= p.y && tx < p.x + p.w! && ty < p.y + p.h!);
  }

  /** На блок-посту его пора проверить (не досматривали последние LAW.border.recheck с). */
  borderDue(c: Character): boolean {
    return this.time - (this.borderChecked.get(c) ?? -1e9) >= LAW.border.recheck;
  }

  judge(target: Character): Verdict {
    const law = target.law;
    let reason: Violation = law.reason ?? 'routine';
    // Подпольщик под личиной показывает чужой паспорт: опознают по фото с шансом (в розыске — всегда); паспорта нет —
    // раскрыт сразу.
    const fake = target.faction === 'rebel' && target.disguised && !!target.passport && !law.wanted && !this.rng.chance(PARTISANS.checkReveal);
    // Не подпольщик с чужим паспортом (снял с тела, отобрал) — фото не его; с поддельным — заметят подделку.
    const pp = target.passport;
    const caught = target.faction !== 'rebel' && !!pp && (pp.forged ? this.rng.chance(PASSPORT.forgedCatch) : foreignPassport(target) && this.rng.chance(PASSPORT.photo));
    // Дело по ориентировке (Suspects): убийство или нападение — арест. Нет дела — причина 'suspect' отпустит ниже.
    const ch = this.charge(target);
    if (target.faction === 'rebel' && !fake) {
      target.disguised = false;
      target.cover = null;
      reason = 'rebel';
    } else if ((target.law.crimeUntil ?? -1) > this.time) reason = 'theft';
    else if ((target.law.riotUntil ?? -1) > this.time) reason = 'riot';
    else if (ch) reason = ch;
    else if (law.wanted && !LAW.arrestFor.includes(reason)) reason = 'wanted';
    else if (caught) {
      // Чужой или поддельный паспорт изъят.
      reason = 'forgery';
      target.passport = null;
      if (target.isPlayer) this.bus.emit('log', { text: PASSPORT.lines.caught, kind: 'law' });
    }
    else if ((!law.hasCid || !target.passport) && !fake) reason = 'no_cid';
    // Блок-пост на стене Верхнего города — досмотр вещей.
    const border = this.atBorder(target);
    if (border) this.borderChecked.set(target, this.time);
    // Свёрток подполья (поручение с доски) — при обыске находят с шансом (на блок-посту — всегда): контрабанда, арест (не
    // при деле об убийстве).
    if (reason !== 'rebel' && !ch && target.inventory.has('parcel_x') && (border || this.rng.chance(ERRANDS.secret.search))) {
      target.inventory.remove('parcel_x', 1);
      reason = 'contraband';
      this.onContraband(target);
      if (target.isPlayer) this.bus.emit('log', { text: border ? LAW.border.lines.parcel : ERRANDS.lines.found, kind: 'law' });
    }
    // Стволы, патроны и гранаты в рюкзаке — изъять (спрятанное под личиной находят не всегда), нарушение — оружие.
    if (border && reason !== 'rebel' && !LAW.arrestFor.includes(reason) && target.inventory.slots.some((st) => confiscable(st.id)) && (!target.disguised || this.rng.chance(LAW.border.findHidden))) {
      this.confiscate(target);
      reason = 'weapon';
      if (target.isPlayer) this.bus.emit('log', { text: LAW.border.lines.found, kind: 'law' });
    }
    if (LAW.arrestFor.includes(reason)) return { kind: 'arrest', reason, fine: 0 };
    // Комендантский час в квартале: штраф уже был недавно — на этот раз арест.
    if (reason === 'zone_curfew' && this.time - (this.zoneCurfewFined.get(target) ?? -1e9) < LAW.zoneCurfewRepeat) return { kind: 'arrest', reason, fine: 0 };
    if (reason === 'running' || reason === 'restricted' || reason === 'insult' || reason === 'fight' || reason === 'zone_curfew') {
      return { kind: 'fine', reason, fine: LAW.fines[reason] };
    }
    // Причина 'suspect' дошла сюда: по ориентировке не доказано и других нарушений нет — отпускают без штрафа.
    return { kind: 'ok', reason, fine: 0 };
  }

  apply(handler: Character, target: Character, verdict: Verdict): void {
    // Заслуги проверявшего (Staffing): задержание, штраф, проверка.
    this.merit(handler, verdict.kind === 'arrest' ? STAFFING.merit.arrest : verdict.kind === 'fine' ? STAFFING.merit.fine : STAFFING.merit.check);
    if (verdict.kind === 'arrest') {
      this.arrest(handler, target, verdict.reason);
      return;
    }
    if (verdict.kind === 'fine') {
      if (cpHas(handler, 'investigate')) verdict = { ...verdict, fine: verdict.fine * LAW.juryFineMul };
      const paid = Math.min(target.money, verdict.fine);
      target.money -= paid;
      handler.money += Math.floor(paid / 2);
      // Комендантский час в квартале — штраф и «по домам».
      handler.say(fill(phrase(this.rng, handler, verdict.reason === 'zone_curfew' ? LINES.cpGoHome : LINES.cpFine, target), { n: verdict.fine }), this.time);
      if (verdict.reason === 'zone_curfew') this.zoneCurfewFined.set(target, this.time);
      adjustLoyalty(target, verdict.reason === 'insult' ? LOYALTY.points.insult : LOYALTY.points.fine, 'штраф', this.bus);
      this.log(`${label(handler)} оштрафовал ${who(target)} на ${verdict.fine} токенов (${VIOLATION_NAMES[verdict.reason]})`, 'law');
      this.onVerdict?.(handler, target, 'fine');
    } else {
      // Ориентировка не подтвердилась — отпускают с другими словами.
      handler.say(phrase(this.rng, handler, verdict.reason === 'suspect' ? SUSPECTS.lines.released : LINES.cpOk, target), this.time);
      adjustLoyalty(target, LOYALTY.points.checkOk, 'проверка пройдена', this.bus);
    }
    this.clear(target);
  }

  /** Снять разбирательство (отпустили или ВС отвлёкся). */
  clear(target: Character): void {
    const law = target.law;
    const wasPlayerCheck = law.handler?.isPlayer;
    // Сняли процедуру с задержанного (конвоир погиб, ВС отвлёкся) — прежний мозг назад, бронь места в
    // камере — снять (иначе «пленник» без процедуры стоит вечно).
    const freed = target.brain instanceof PrisonerBrain && !!law.savedBrain;
    const wasReleasing = law.phase === 'releasing';
    if (freed) {
      if (law.phase === 'cuffed' || law.phase === 'entering') this.vacate(target);
      this.restoreBrain(target);
    }
    law.phase = 'none';
    if (freed && wasReleasing) this.onReleased?.(target);
    law.handler = null;
    law.reason = null;
    if (wasPlayerCheck) this.bus.emit('law:checkClosed', { target });
  }

  /** ВС потерял беглеца — тот в розыске. */
  lost(target: Character): void {
    const handler = target.law.handler;
    this.declare(target, 'flight');
    if (handler) {
      handler.say(phrase(this.rng, handler, LINES.cpLost), this.time);
      if (this.onLost && !handler.isPlayer) this.onLost(handler, target);
      else this.log(`${label(handler)}: потерял ${who(target)}, объявлен в розыск`, 'radio');
    }
    this.clear(target);
  }

  /** Отсидевшего отпустили (мозг уже прежний) — подполье даёт ему документы и уводит в схрон. */
  onReleased: ((c: Character) => void) | null = null;
  /** Рация (Radio): нарушитель побежал от юнита, юнит его упустил, задержание (fled — после погони). */
  onFlee: ((handler: Character, target: Character) => void) | null = null;
  onLost: ((handler: Character, target: Character) => void) | null = null;
  onArrest: ((handler: Character, target: Character, fled: boolean) => void) | null = null;
  /** Решение по проверке (арест, штраф, отпустили) — Relations: обида на ВС у задержанного и его близких. */
  onVerdict: ((handler: Character, target: Character, kind: 'arrest' | 'fine' | 'ok') => void) | null = null;

  arrest(handler: Character, target: Character, reason: Violation): void {
    const law = target.law;
    if (law.phase === 'cuffed' || law.phase === 'entering' || law.phase === 'jailed') return;
    const wasPlayerCheck = law.handler?.isPlayer && law.phase === 'checking';
    const fled = law.phase === 'fleeing';
    law.phase = 'cuffed';
    law.handler = handler;
    law.reason = reason;
    law.since = this.time;
    // Взяли снова, пока ещё выводят (мозг — пленника): прежний настоящий мозг не терять.
    if (!(target.brain instanceof PrisonerBrain)) law.savedBrain = target.brain;
    target.brain = new PrisonerBrain(target);
    // Задержанный повстанец больше не под личиной.
    if (target.faction === 'rebel') {
      target.disguised = false;
      target.cover = null;
    }
    // В наручниках ствол не держат.
    if (target.weapon) {
      target.mags[target.weapon] = target.mag;
      target.weapon = null;
    }
    // В наручниках не упирается: конвоир и прохожие легко отталкивают.
    target.mass = PRISONER_MASS;
    target.wantX = target.wantY = 0;
    // Задержан — уже не опасен; дело по нему (Suspects) закрыто.
    target.hostile = false;
    this.closeCase(target);
    handler.say(phrase(this.rng, handler, LINES.cpArrest, target), this.time);
    adjustLoyalty(target, LOYALTY.points.arrest, 'задержание', this.bus);
    this.log(`${label(handler)} задержал ${who(target)} (${VIOLATION_NAMES[reason]})`, 'law');
    if (wasPlayerCheck) this.bus.emit('law:checkClosed', { target });
    this.onArrest?.(handler, target, fled);
    this.onVerdict?.(handler, target, 'arrest');
  }

  /** Свободное место (не занято и не зарезервировано) в камере или -1. */
  private freeSlot(cell: Cell): number {
    return cell.slots.findIndex((s) => !s.occupant && !s.reserved);
  }

  /** Место персонажа в камере (занятое или зарезервированное) или null. */
  slotOf(cell: Cell, c: Character): CellSlot | null {
    return cell.slots.find((s) => s.occupant === c || s.reserved === c) ?? null;
  }

  /** Сколько сидит в камере. */
  occupants(cell: Cell): Character[] {
    const out: Character[] = [];
    for (const s of cell.slots) if (s.occupant) out.push(s.occupant);
    return out;
  }

  /**
   * Камера со свободным местом — ближайшая к точке. Повстанцев (армия, подполье) — в тюрьму Протектората
   * (мест нет — в КПЗ); граждан — сперва в общую камеру КПЗ, остальных — сперва в одиночные; нет места —
   * в любую камеру КПЗ. В тюрьму сажают только повстанцев.
   */
  freeCell(x: number, y: number, prisoner: Character | null = null): Cell | null {
    const wantCommon = prisoner ? belongsInCommon(prisoner) : false;
    const wantPrison = prisoner ? belongsInPrison(prisoner) : false;
    const prisonFree = wantPrison && this.cells.some((o) => o.prison && this.freeSlot(o) >= 0);
    let best: Cell | null = null;
    let bestD = Infinity;
    for (const c of this.cells) {
      if (this.freeSlot(c) < 0) continue;
      if (c.prison !== prisonFree) continue;
      const d = Math.hypot(c.frontX - x, c.frontY - y) + (c.common === wantCommon ? 0 : 1e6);
      if (d < bestD) {
        bestD = d;
        best = c;
      }
    }
    return best;
  }

  reserve(cell: Cell, prisoner: Character): void {
    if (this.slotOf(cell, prisoner)) return;
    const k = this.freeSlot(cell);
    if (k >= 0) cell.slots[k].reserved = prisoner;
  }

  /** Снять бронь места (конвой сорвался). */
  unreserve(cell: Cell, prisoner: Character): void {
    for (const s of cell.slots) if (s.reserved === prisoner) s.reserved = null;
  }

  /** Конвоир у двери камеры: открыть, завести. */
  putInCell(prisoner: Character, cell: Cell): void {
    const law = prisoner.law;
    law.phase = 'entering';
    law.cell = cell.index;
    this.reserve(cell, prisoner);
    if (cell.door) {
      this.doors.setLocked(cell.door, false);
      this.doors.open(cell.door);
    }
  }

  /** Освободить место персонажа во всех камерах (дверь запрёт update, если там ещё кто-то сидит). */
  vacate(c: Character): void {
    for (const cell of this.cells) {
      for (const s of cell.slots) {
        if (s.occupant === c || s.reserved === c) {
          s.occupant = null;
          s.reserved = null;
          if (cell.door) this.doors.setLocked(cell.door, false);
        }
      }
    }
  }

  /** Снять с персонажа любые процедуры (гибель, смена роли): освободить камеру, вернуть мозг. */
  release(c: Character): void {
    this.vacate(c);
    this.evidence.delete(c);
    this.releaseSpot.delete(c);
    c.law.cell = -1;
    if (c.law.savedBrain || c.brain instanceof PrisonerBrain) this.restoreBrain(c);
    this.clear(c);
  }

  /** Отпустить без камеры (КПЗ переполнены). */
  releaseNoCell(handler: Character, prisoner: Character): void {
    handler.say(this.rng.pick(LINES.noCellFree), this.time);
    const paid = Math.min(prisoner.money, LAW.fines.restricted);
    prisoner.money -= paid;
    this.restoreBrain(prisoner);
    this.clear(prisoner);
  }

  private restoreBrain(p: Character): void {
    p.mass = p.isPlayer ? CHARACTER.mass.player : CHARACTER.mass.npc;
    p.brain = p.law.savedBrain;
    p.law.savedBrain = null;
    p.wantX = p.wantY = 0;
  }

  /** Точка в какой-нибудь камере КПЗ или тюрьмы (с запасом r px) — туда никого не ставят при заселении. */
  inAnyCell(x: number, y: number, r = 0): boolean {
    const ts = this.map.tileSize;
    return this.cells.some((c) => x > c.bounds.x0 * ts - r && y > c.bounds.y0 * ts - r && x < (c.bounds.x1 + 1) * ts + r && y < (c.bounds.y1 + 1) * ts + r);
  }

  private inside(c: Cell, x: number, y: number): boolean {
    const ts = this.map.tileSize;
    return x > c.bounds.x0 * ts && y > c.bounds.y0 * ts && x < (c.bounds.x1 + 1) * ts && y < (c.bounds.y1 + 1) * ts;
  }

  /** Сколько секунд до снятия розыска (null — не в розыске; Infinity — бессрочно). */
  wantedLeft(c: Character): number | null {
    if (!c.law.wanted) return null;
    return Math.max(0, chargeDef(c).term - (this.time - (this.wantedAt.get(c) ?? this.time)));
  }

  /**
   * Срок заключения (LAW.wanted.charges.jail): по статье ареста (убийство, нападение — дело Suspects) или розыска;
   * повстанец-NPC в тюрьме — бессрочно (вызволяют штурмом); прочие аресты в КПЗ — LAW.jailTime. Игроку — не больше
   * LAW.wanted.playerJail; пришёл с повинной — × surrender.jailMul.
   */
  private jailTerm(c: Character, prison: boolean): number {
    const law = c.law;
    const W = LAW.wanted;
    if (prison && c.faction === 'rebel') return c.isPlayer ? LAW.prison.playerTime : Infinity;
    const charge: WantedCharge | null = law.reason === 'murder' ? 'murder' : law.reason === 'assault' ? 'assault' : law.wanted ? chargeOf(c) : null;
    let t = charge ? W.charges[charge].jail : c.isPlayer ? LAW.jailTime.player : LAW.jailTime.npc;
    if (c.isPlayer) t = Math.min(t, W.playerJail);
    if (law.surrendered) t *= W.surrender.jailMul;
    return t;
  }

  /** За что сидит (статья) — для журнала. */
  private chargeName(c: Character): string {
    const r = c.law.reason;
    return r === 'murder' || r === 'assault' ? LAW.wanted.charges[r].name : chargeDef(c).name;
  }

  /** Снять розыск (отсидел, явка с повинной за мелкое, новые документы). */
  pardon(c: Character): void {
    c.law.wanted = false;
    c.law.wantedFor = undefined;
    c.law.surrendered = false;
    this.wantedAt.delete(c);
  }

  /**
   * Объявить в розыск по статье (LAW.wanted.charges): статья тяжелее прежней — заменяет её; срок ориентировки —
   * заново. Игроку — в журнал, за что и насколько.
   */
  declare(c: Character, charge: WantedCharge): void {
    const law = c.law;
    const C = LAW.wanted.charges;
    const prev = law.wanted ? law.wantedFor ?? 'flight' : null;
    if (!prev || C[charge].level >= C[prev].level) law.wantedFor = charge;
    law.wanted = true;
    this.wantedAt.set(c, this.time);
    if (c.isPlayer && law.wantedFor !== prev) {
      const d = chargeDef(c);
      const term = Number.isFinite(d.term) ? `ориентировку снимут через ${Math.round(d.term / 60)} мин, если не попадётесь ВС` : 'бессрочно';
      this.log(`Вы объявлены в розыск: ${d.name} (${'★'.repeat(d.level)}) — ${term}.`, 'law');
    }
  }

  /**
   * Срок розыска (LAW.wanted, по статье): идёт с последнего «засвета»; пока враг Протектората (hostile) или в руках ВС —
   * не идёт. Истёк — розыск снят. Раньше розыск не снимался никогда: бандит, раз напавший на ВС, навсегда выпадал
   * из дел банды, а игрок мог его снять только отсидкой или «липой».
   */
  private updateWanted(): void {
    for (const c of this.entities.list) {
      if (!c.alive || !c.law.wanted) continue;
      const at = this.wantedAt.get(c);
      if (at === undefined || c.hostile || c.law.phase !== 'none') {
        this.wantedAt.set(c, this.time);
        continue;
      }
      if (this.time - at < chargeDef(c).term) continue;
      c.law.wanted = false;
      c.law.wantedFor = undefined;
      this.wantedAt.delete(c);
      if (c.isPlayer) this.log('Розыск снят: ориентировка устарела.', 'law');
    }
  }

  update(dt: number, player: Character | null): void {
    this.time += dt;
    this.updateWanted();
    for (const c of this.entities.list) {
      const law = c.law;
      switch (law.phase) {
        case 'ordered':
        case 'checking': {
          const h = law.handler;
          if (!h || !h.alive) {
            this.clear(c);
            break;
          }
          // Игрок, которому приказали стоять, но он уходит — сопротивление.
          if (c.isPlayer && this.time - law.since > LAW.complyGrace) {
            const moved = Math.hypot(c.x - law.orderX, c.y - law.orderY);
            if (moved > LAW.complyRadius) {
              this.log(`Вы не подчинились приказу ${label(h)}!`, 'law');
              this.startFlee(c);
            }
          }
          // Игрок-ВС ушёл от задержанного — отпускаем.
          if (h.isPlayer && Math.hypot(h.x - c.x, h.y - c.y) > 90) this.clear(c);
          break;
        }
        case 'cuffed': {
          const h = law.handler;
          if (!h || !h.alive) {
            this.restoreBrain(c);
            this.clear(c);
            break;
          }
          // Игрок-ВС привёл задержанного к свободной камере — заводим.
          if (h.isPlayer) {
            const cell = this.freeCell(h.x, h.y, c);
            if (cell && Math.hypot(h.x - cell.frontX, h.y - cell.frontY) < 56) this.putInCell(c, cell);
          }
          break;
        }
        case 'entering': {
          const cell = this.cells[law.cell];
          const slot = cell ? this.slotOf(cell, c) : null;
          if (cell && slot && this.inside(cell, c.x, c.y) && Math.hypot(c.x - slot.x, c.y - slot.y) < 20) {
            slot.occupant = c;
            slot.reserved = null;
            law.phase = 'jailed';
            law.handler = null;
            c.hostile = false;
            this.closeCase(c);
            const term = this.jailTerm(c, !!cell.prison);
            if (cell.prison) {
              // Тюрьма: срок по статье (повстанцам — бессрочно, игроку — срок по статье), оружие — в комнату изъятого.
              law.jailUntil = this.time + term;
              this.confiscate(c);
              this.log(`${who(c, true)} помещён в тюрьму Протектората${Number.isFinite(term) ? ` на ${Math.round(term)} с (${this.chargeName(c)})` : ' — бессрочно'}`, 'law');
            } else {
              law.jailUntil = this.time + term;
              law.wanted = false;
              law.wantedFor = undefined;
              law.surrendered = false;
              law.hasCid = true;
              // Оружие, патроны и гранаты изымают и после срока не возвращают (раньше бандит выходил из
              // ворот Управы со стволом в руках — и его тут же задерживали снова, по кругу).
              this.confiscate(c);
              this.log(`${who(c, true)} помещён в ${cell.common ? 'общую камеру' : 'КПЗ'} на ${Math.round(law.jailUntil - this.time)} с`, 'law');
            }
          } else if (this.time - law.since > 25) {
            // Застрял на входе — всё равно считаем посаженным.
            law.since = this.time;
          }
          break;
        }
        case 'jailed':
          if (this.time >= law.jailUntil) {
            const cell = this.cells[law.cell];
            if (cell) {
              const slot = this.slotOf(cell, c);
              if (slot) slot.occupant = null;
              if (cell.door) {
                this.doors.setLocked(cell.door, false);
                this.doors.open(cell.door);
              }
            }
            law.phase = 'releasing';
            law.since = this.time;
            law.cell = -1;
            // Отсидел — документы в порядке: какое-то время его не проверяют (LAW.releasedGrace).
            if (!cell?.prison) law.lastCheck = this.time + LAW.releasedGrace - LAW.recheckCooldown;
            // Отсидевшему изъятое оружие не вернут, остальное — да. Отсидел по статье — розыск снят (повстанец остаётся
            // повстанцем), документы в порядке.
            this.returnEvidence(c, false);
            if (c.faction !== 'rebel') {
              law.wanted = false;
              law.wantedFor = undefined;
              law.hasCid = true;
            }
            law.surrendered = false;
            if (cell?.prison && this.prisonGate) this.releaseSpot.set(c, this.prisonGate);
            this.log(`${who(c, true)} отбыл срок и отпущен`, 'law');
            if (c.isPlayer) {
              this.restoreBrain(c);
              this.clear(c);
            }
          }
          break;
        case 'releasing':
          // PrisonerBrain выводит к воротам Управы и сообщает done.
          if ((c.brain as PrisonerBrain | null)?.done || this.time - law.since > 30) {
            this.releaseSpot.delete(c);
            this.restoreBrain(c);
            this.clear(c);
            this.onReleased?.(c);
          }
          break;
        case 'fleeing':
          if (!law.handler || !law.handler.alive) this.clear(c);
          break;
      }
    }
    this.lockCells();
    void player;
  }

  /**
   * Дверь камеры заперта, пока там кто-то сидит и никто не входит и не выходит: в общей камере
   * новичка заводят и отпускают отсидевшего, не выпуская остальных.
   */
  private lockCells(): void {
    for (const cell of this.cells) {
      if (!cell.door || cell.brokenUntil > this.time) continue;
      let seated = false;
      let moving = false;
      for (const s of cell.slots) {
        if (s.occupant) seated = true;
        if (s.reserved && s.reserved.law.phase === 'entering') moving = true;
      }
      if (!seated || moving) continue;
      if (!cell.common && !cell.prison) {
        this.doors.setLocked(cell.door, true);
        continue;
      }
      // Отпущенный ещё внутри — не запирать, пока не выйдет.
      for (const o of this.entities.list) {
        if (o.law.phase === 'releasing' && this.inside(cell, o.x, o.y)) {
          moving = true;
          break;
        }
      }
      if (!moving) this.doors.setLocked(cell.door, true);
    }
  }

  log(text: string, kind: 'law' | 'radio' | 'world' = 'law'): void {
    this.bus.emit('log', { text, kind });
  }

  /**
   * Взломали дверь камеры: все, кто сидит, выходят — и в розыск; дверь не запирается LAW.brokenDoor с.
   * Из тюрьмы освобождённые сразу свободны: вооружаются в оружейной и забирают своё из комнаты изъятого
   * (onFreed решает, куда им дальше). Возвращает, сколько сбежало.
   */
  breakCell(cell: Cell): number {
    let n = 0;
    for (const s of cell.slots) {
      const c = s.occupant ?? s.reserved;
      s.occupant = null;
      s.reserved = null;
      if (!c || !c.alive) continue;
      n++;
      if (cell.prison) {
        // Изъятое остаётся в комнате улик — беглый заберёт сам (или вооружится в оружейной).
        c.law.cell = -1;
        this.declare(c, 'escape');
        if (c.law.savedBrain || c.brain instanceof PrisonerBrain) this.restoreBrain(c);
        this.clear(c);
        this.declare(c, 'escape');
        this.onFreed?.(c);
        continue;
      }
      c.law.phase = 'releasing';
      c.law.since = this.time;
      c.law.cell = -1;
      this.declare(c, 'escape');
      if (c.isPlayer) {
        this.restoreBrain(c);
        this.clear(c);
        this.declare(c, 'escape');
      }
    }
    cell.brokenUntil = this.time + LAW.brokenDoor;
    if (cell.door) {
      this.doors.setLocked(cell.door, false);
      this.doors.open(cell.door);
    }
    return n;
  }

  /** Освобождённого своими из тюрьмы — куда ему дальше (задаёт InsurgencySystem). */
  onFreed: ((c: Character) => void) | null = null;

  /** Кто сидит в тюрьме Протектората. */
  imprisoned(): Character[] {
    const out: Character[] = [];
    for (const cell of this.cells) if (cell.prison) for (const s of cell.slots) if (s.occupant) out.push(s.occupant);
    return out;
  }

  /** Камеры тюрьмы. */
  get prisonCells(): Cell[] {
    return this.cells.filter((c) => c.prison);
  }

  /** Есть ли тюрьма на карте. */
  get hasPrison(): boolean {
    return this.cells.some((c) => c.prison);
  }

  /** Стволы, патроны и гранаты — в комнату изъятого (в тюрьме — при оформлении в приёмной). */
  confiscate(c: Character): void {
    const taken = this.evidence.get(c) ?? [];
    for (let i = c.inventory.slots.length - 1; i >= 0; i--) {
      const st = c.inventory.slots[i];
      if (!confiscable(st.id)) continue;
      taken.push({ id: st.id, qty: st.qty });
      c.inventory.slots.splice(i, 1);
    }
    if (c.weapon) c.mags[c.weapon] = c.mag;
    c.weapon = null;
    if (taken.length) this.evidence.set(c, taken);
  }

  /** Вернуть изъятое (weapons — и стволы с патронами; иначе они остаются в тюрьме). */
  returnEvidence(c: Character, weapons: boolean): void {
    const taken = this.evidence.get(c);
    if (!taken) return;
    this.evidence.delete(c);
    for (const st of taken) if (weapons || !confiscable(st.id)) c.inventory.add(st.id, st.qty);
  }

  /** Ячейка НавГрида для точки перед камерой. */
  frontAnchor(cell: Cell): number {
    return this.nav.nearestWalkable(cell.frontX, cell.frontY, 4);
  }

  /** Якорь места персонажа в камере (без брони — центр камеры). */
  cellAnchor(cell: Cell, c: Character | null = null): number {
    const slot = c ? this.slotOf(cell, c) : null;
    return this.nav.nearestWalkable(slot?.x ?? cell.x, slot?.y ?? cell.y, 3);
  }
}

/** «ВС-2231» / «Иван Попов». */
export function label(c: Character): string {
  return c.isPlayer ? `${c.name} (вы)` : c.name;
}

/** «гражданина #48102» — как в радиопереговорах. */
export function who(c: Character, nominative = false): string {
  if (c.isPlayer) return nominative ? 'Вы' : 'вас';
  const f = c.faction === 'rebel' ? (nominative ? 'Повстанец' : 'повстанца') : c.faction === 'cwu' ? (nominative ? 'Рабочий ТС' : 'рабочего ТС') : nominative ? 'Гражданин' : 'гражданина';
  return `${f} #${c.cid}`;
}
