/** Описание системы — docs/economy.md. */
import type { Character } from '../entities/Character';
import { STAFFING } from '../config/staffing';
import type { AiContext } from '../ai/AiContext';
import { CRIME } from '../config/crime';
import { FACTIONS } from '../config/factions';
import { CpBrain } from '../ai/brains/CpBrain';
import { angleDiff, type Corpse } from './CombatSystem';

const near: Character[] = [];
const DEG = Math.PI / 180;

/**
 * Кражи: карманная (вор за спиной у прохожего) и взлом раздатчика рационов (вор с отмычкой, пока
 * окно закрыто). После кражи вор «засвечен» CRIME.seenFor с — ВС, который его увидит, задержит за
 * кражу (LawSystem.observe → 'theft'). Жертва может заметить и закричать — ближайший ВС идёт на крик.
 */
export class CrimeSystem {
  /** Счётчики (тесты, отладка). */
  stats = { pickpockets: 0, robberies: 0, stolen: 0, hacks: 0, cries: 0, corpseLoots: 0 };

  constructor(private readonly ctx: AiContext) {}

  /** Стоит ли вор за спиной у жертвы и рядом. */
  behind(thief: Character, victim: Character): boolean {
    const P = CRIME.pickpocket;
    if (Math.hypot(victim.x - thief.x, victim.y - thief.y) > P.reach) return false;
    const toThief = Math.atan2(thief.y - victim.y, thief.x - victim.x);
    return Math.abs(angleDiff(toThief, victim.facing)) > P.behindDeg * DEG;
  }

  /** Можно ли обокрасть: не власть, не поднадзорный, не в разбирательстве, есть деньги. */
  victimOk(thief: Character, v: Character): boolean {
    return v !== thief && v.alive && !FACTIONS[v.faction].authority && v.faction !== 'vort' && v.law.phase === 'none' && v.money > 0;
  }

  /** Карманная кража (после выдержки CRIME.pickpocket.time). Возвращает, сколько украдено. */
  pickpocket(thief: Character, victim: Character): number {
    const P = CRIME.pickpocket;
    const rng = this.ctx.rng;
    if (!this.victimOk(thief, victim)) return 0;
    const mul = thief.profession === 'thief' ? P.thiefMul : 1;
    const amount = Math.min(victim.money, Math.round(rng.range(P.amount[0], P.amount[1]) * mul));
    victim.money -= amount;
    thief.money += amount;
    this.stats.pickpockets++;
    this.stats.stolen += amount;
    this.flag(thief);
    if (thief.isPlayer) this.ctx.bus.emit('log', { text: `Вы вытащили у прохожего ${amount} токенов. Не попадитесь ВС на глаза ${CRIME.seenFor} с.`, kind: 'world' });
    if (victim.isPlayer) {
      this.ctx.bus.emit('log', { text: `У вас вытащили ${amount} токенов!`, kind: 'law' });
      this.ctx.relations?.event('rob', thief, victim);
    } else if (rng.chance(P.noticeChance)) {
      this.cry(victim, thief);
      this.ctx.relations?.event('rob', thief, victim);
    }
    return amount;
  }

  /** Можно ли ограбить: как для кражи, и жертва — в подворотне (жилые кварталы, промзона). */
  robOk(bandit: Character, v: Character): boolean {
    if (!this.victimOk(bandit, v)) return false;
    // На районе своей банды — где угодно: чужим там не рады.
    const g = this.ctx.gangs?.of(bandit);
    if (g && v.gang !== g.id && this.ctx.gangs.inTurf(g, v.x, v.y)) return true;
    const kind = this.ctx.map.zoneAtWorld(v.x, v.y)?.kind;
    return !!kind && (CRIME.rob.zones as readonly string[]).includes(kind);
  }

  /** Гоп-стоп (после выдержки CRIME.rob.time со стволом в руках). Возвращает, сколько отдали. */
  rob(bandit: Character, victim: Character): number {
    const R = CRIME.rob;
    const rng = this.ctx.rng;
    if (!this.victimOk(bandit, victim)) return 0;
    const amount = Math.min(victim.money, Math.round(rng.range(R.amount[0], R.amount[1])));
    victim.money -= amount;
    bandit.money += amount;
    this.stats.robberies++;
    this.stats.stolen += amount;
    this.flag(bandit);
    this.ctx.relations?.event('rob', bandit, victim);
    if (bandit.isPlayer) this.ctx.bus.emit('log', { text: `Прохожий отдал ${amount} токенов. Уходите, пока не прибежали ВС.`, kind: 'world' });
    if (victim.isPlayer) this.ctx.bus.emit('log', { text: `Вас ограбили на ${amount} токенов!`, kind: 'law' });
    else {
      victim.say(rng.pick(['Не стреляй! Бери всё!', 'Ладно, ладно, забирай…']), this.ctx.law.now, 2);
      if (rng.chance(R.cryChance)) {
        const now = this.ctx.law.now;
        victim.say(rng.pick(['Грабят!', 'Помогите! Грабят!', 'ВС! Бандит!']), now + 1.2, 2.5);
        this.cry(victim, bandit, false);
      }
    }
    return amount;
  }

  /** Взлом раздатчика рационов: забрать до CRIME.hack.rations со склада будки; отмычка может сломаться. */
  hackDispenser(thief: Character): number {
    const eco = this.ctx.economy;
    const H = CRIME.hack;
    if (eco.open || !thief.inventory.has('lockpick')) return 0;
    const n = Math.min(eco.rationStock, H.rations);
    eco.rationStock -= n;
    if (n > 0) thief.inventory.add('ration', n);
    if (this.ctx.rng.chance(H.lockpickBreak)) thief.inventory.remove('lockpick', 1);
    this.stats.hacks++;
    this.flag(thief);
    this.ctx.bus.emit('log', { text: 'ТС: раздатчик рационов взломан! Недостача на складе будки.', kind: 'world' });
    return n;
  }

  /**
   * Наблюдатель OBS отсканировал тело: убийца (если не сотрудник Протектората) объявлен в розыск,
   * «Надзор» знает, где он сейчас. Возвращает текст для журнала.
   * Уголовное дело (Suspects): экспертиза и свидетели называют виновника сами (розыск — при опознании),
   * скан лишь открывает дело. Без дела (война, Протекторат, не в городе) — как раньше.
   */
  investigate(corpse: Corpse, obs: Character): string {
    corpse.scanned = true;
    const k = corpse.killer;
    const zone = this.ctx.map.zoneAtWorld(corpse.x, corpse.y)?.name ?? 'город';
    if (!k) return `Скан тела: ${corpse.name} — причина смерти не установлена.`;
    if (FACTIONS[k.faction].authority) return `Скан тела: ${corpse.name} — ликвидирован сотрудником Протектората (${k.name}).`;
    const r = this.ctx.suspects?.enabled ? this.ctx.suspects.forensic(corpse, obs) : null;
    if (r !== null) {
      if (!r) return `Надзор: скан тела (${zone}) — ${corpse.name}: виновник не установлен, дело открыто.`;
      this.ctx.staffing?.merit(obs, STAFFING.merit.investigate);
      return `Надзор: скан тела (${zone}) — ${corpse.name}: виновник установлен.`;
    }
    this.ctx.law.declare(k, FACTIONS[corpse.faction].authority ? 'attackCp' : 'murder');
    // Заслуга следователя: убийца найден.
    this.ctx.staffing?.merit(obs, STAFFING.merit.investigate);
    if (k.alive) {
      this.ctx.war.operatives.add(k);
      this.ctx.war.lastKnown.set(k, { x: k.x, y: k.y });
    }
    const who = k.isPlayer ? 'ВЫ' : k.name;
    const text = `Надзор: скан тела (${zone}) — убийца ${who}${k.passport ? `, паспорт № ${k.passport.no}` : ''}. Объявлен в розыск.`;
    this.ctx.bus.emit('log', { text, kind: 'radio' });
    if (k.isPlayer) this.ctx.bus.emit('announce', { text: 'Вас объявили в розыск' });
    void obs;
    return text;
  }

  /** «Засветился»: ВС, увидевший вора в ближайшие секунды, задержит его. */
  private flag(thief: Character): void {
    thief.law.crimeUntil = this.ctx.law.now + CRIME.seenFor;
  }

  /** Жертва кричит «Держи вора!» — ближайший свободный патрульный идёт разбираться. */
  cry(victim: Character, thief: Character, shout = true): void {
    const now = this.ctx.law.now;
    if (shout) victim.say(this.ctx.rng.pick(['Держи вора!', 'Эй! Мой кошелёк!', 'Вор! Помогите!']), now, 2.5);
    this.stats.cries++;
    for (const o of this.ctx.entities.near(victim.x, victim.y, CRIME.pickpocket.cryRange, near)) {
      if (!(o.brain instanceof CpBrain) || o.brain.target || o.brain.guardPost || !o.alive) continue;
      if (thief.law.phase !== 'none') return;
      thief.law.crimeUntil = now + CRIME.seenFor;
      o.brain.engage(thief, 'theft');
      return;
    }
  }
}
