/** Описание системы — docs/rendering.md. */
import { WEAPON_POSE } from '../config/weaponSprites';
import type { FactionId } from '../config/factions';
import { PAWN } from '../config/pawns';
import { cpUnit } from '../config/factions';
import { accBack, accBody, accTop, accessoriesOf, flakBody, flakHelmet, gasMaskHead, peakedCap, reconBody, reconHelmet } from './pawnArmor';
import type { ProfessionId } from '../config/professions';
import { bodyPath, fillStroke, headPath, roundRect, stroke, tint } from './pawnShapes';
import { balaclava, gasMaskS10, michHelmet, tacticalBody, tacticalFace } from './pawnTactical';
import { clothedBody, clothesHead, clothesNeck, faceMask, hidesHair, hood } from './pawnClothes';
import { REBEL_KITS, kitFrom, rebelKitIds, unitKit, type KitLook } from '../config/uniforms';
import type { ClothesLook } from '../config/clothes';

export { tint };

export type PawnDir = 'S' | 'N' | 'E' | 'W';

/** Внешность пешки: фракция и ранг (цвет формы/брони), зерно (кожа, волосы, причёска). */
export interface PawnLook {
  faction: FactionId;
  rank: number;
  color: string;
  seed: number;
  /** Профессия — своя одежда поверх фракционной (халат, колпак, капюшон…). */
  profession?: ProfessionId | null;
  /** Семья: зерно общей внешности (кожа, волосы) и цвет повязки на рукаве. */
  kin?: number;
  band?: string;
  /** Надетые шлем и бронежилет (systems/Gear): цвет; поверх гражданской одежды. */
  helmet?: string;
  vest?: string;
  /** Гражданская одежда по достатку (config/clothes.ts) — вместо одежды фракции; ключ — для кэша спрайтов. */
  clothes?: ClothesLook | null;
  /**
   * Форма по частям (config/uniforms.ts): шлем, противогаз, рубаха, броня, шинель, ранец. undefined — у ВС форма юнита
   * целиком (по рангу), у остальных — нет; null — без формы.
   */
  kit?: KitLook | null;
  clothesKey?: string;
  /** Мимика на этот кадр: глаза закрыты (моргнул, спит), рот открыт (говорит). */
  blink?: boolean;
  talk?: boolean;
}

type Outfit = Record<string, string | boolean | number>;

/** Одежда пешки: фракционная, поля профессии перекрывают. */
function outfitOf(look: PawnLook): Outfit {
  let base = PAWN.outfits[look.faction] ?? PAWN.outfits.citizen;
  // ВС — снаряжение по юниту (каска и жилет PCU, рекон-броня SU, силовая броня главы).
  if (look.faction === 'cp') base = { ...base, ...PAWN.cpUnits[cpUnit(look.rank).unit] };
  const prof = look.profession ? PAWN.professionOutfits[look.profession] : undefined;
  const o = prof ? { ...base, ...prof } : base;
  // Повязка семьи — если своей (медик, глава) нет.
  return look.band && !o.armband ? { ...o, armband: look.band } : o;
}

/** Армия сопротивления в перчатках (военная экипировка). */
const GLOVED_REBELS = new Set(['rebel_soldier', 'veteran', 'rebel_medic', 'pyro', 'demolitionist', 'rebel_leader', 'hydra_rct', 'hydra_sergeant', 'hydra_sniper', 'commando']);

/** Цвет рук на оружии: перчатки у силовиков, OTA и армии, иначе кожа (как у головы). */
export function handColor(look: Pick<PawnLook, 'faction' | 'profession' | 'seed' | 'kin' | 'clothes' | 'kit'>): string {
  if (look.kit && look.faction === 'cp') return WEAPON_POSE.gloves;
  if (look.clothes) return pick(PAWN.skins, look.kin ?? look.seed, 3);
  if (look.faction === 'cp' || look.faction === 'ota') return WEAPON_POSE.gloves;
  if (look.faction === 'rebel' && look.profession && GLOVED_REBELS.has(look.profession)) return WEAPON_POSE.gloveRebel;
  return pick(PAWN.skins, look.kin ?? look.seed, 3);
}

/** Цвет обуви (ступни при ходьбе) по фракции — без сборки одежды: зовётся каждый кадр. */
export function bootColor(look: Pick<PawnLook, 'faction' | 'clothes'>): string {
  return look.clothes?.boots ?? PAWN.boots[look.faction] ?? PAWN.gear.boot;
}

type HairStyle = keyof typeof PAWN.hairStyles;
type Ctx = CanvasRenderingContext2D;

/** Сторона взгляда по углу (как в RimWorld: четыре стороны). */
export function pawnDir(facing: number): PawnDir {
  const c = Math.cos(facing);
  const s = Math.sin(facing);
  if (Math.abs(c) >= Math.abs(s)) return c >= 0 ? 'E' : 'W';
  return s >= 0 ? 'S' : 'N';
}

/** Зерно внешности из строки (имя тела) или числа (id персонажа). */
export function lookSeed(v: string | number): number {
  if (typeof v === 'number') return Math.imul(v ^ 0x9e3779b9, 2654435761) >>> 0;
  let h = 2166136261;
  for (let i = 0; i < v.length; i++) h = Math.imul(h ^ v.charCodeAt(i), 16777619);
  return h >>> 0;
}

function pick<T>(list: readonly T[], seed: number, salt: number): T {
  return list[(((seed >>> salt) ^ Math.imul(seed, salt + 7)) >>> 0) % list.length];
}

function hairStyleOf(seed: number): HairStyle {
  let roll = ((seed >>> 13) % 1000) / 1000;
  for (const [k, p] of Object.entries(PAWN.hairStyles) as [HairStyle, number][]) {
    if ((roll -= p) < 0) return k;
  }
  return 'short';
}


/**
 * Пешка в стиле RimWorld. x, y — экран (центр персонажа), s — пикселей экрана на px мира.
 * Запад — отражение востока. Тень — отдельно (drawPawnShadow).
 */
export function drawPawn(ctx: Ctx, look: PawnLook, x: number, y: number, s: number, dir: PawnDir): void {
  ctx.save();
  ctx.translate(x, y);
  ctx.scale(dir === 'W' ? -s : s, s);
  const d: PawnDir = dir === 'W' ? 'E' : dir;
  ctx.lineJoin = 'round';
  ctx.lineCap = 'round';
  const O = outfitOf(look);
  const base = O.base === 'rank' ? look.color : (O.base as string);
  const armor = look.vest ?? (O.armor === 'rank' ? look.color : (O.armor as string | undefined));
  const vest = !!look.vest || (!!armor && O.vest !== false && look.rank >= ((O.vestFromRank as number | undefined) ?? 99));
  let head = O.head as string;
  // Надетый шлем — вместо кепки, колпака и капюшона.
  if (look.helmet && (head === 'cap' || head === 'chef' || head === 'hood' || head === 'bandana' || head === 'beret')) head = 'hair';
  if (head === 'bandana' && !vest) head = 'hair';
  const hairy = head === 'hair' || head === 'bandana' || head === 'cap' || head === 'chef' || head === 'beret';
  // В гражданском (горожанин, опер в штатском) — своя причёска, а не голова под шлемом формы.
  const style: HairStyle = hairy || look.clothes ? hairStyleOf(look.seed) : 'bald';
  // Родня похожа: кожа и цвет волос — от зерна семьи.
  const skin = pick(PAWN.skins, look.kin ?? look.seed, 3);
  const hair = pick(PAWN.hairs, look.kin ?? look.seed, 11);
  const H = PAWN.head;
  const hx = d === 'E' ? H.sideShift : 0;
  faceOf.seed = look.kin !== undefined ? (look.seed ^ (look.kin * 7)) : look.seed;
  faceOf.hair = hair;
  faceOf.style = style;
  faceOf.blink = !!look.blink;
  faceOf.talk = !!look.talk;

  // Форма по частям (ВС и всякий, кто надел её части): слоями поверх одежды.
  const K = kitLookOf(look, O);
  if (K) {
    kitPawn(ctx, d, look, K, base, skin, hair, style, hx);
    ctx.restore();
    return;
  }
  // OTA и глава восстания: силовая броня по эскизам RimWorld, аксессуары за спиной, на туловище и поверх головы.
  if (!look.clothes && (O.style === 'marine' || O.style === 'flak' || O.style === 'recon')) {
    const trim = O.trim === 'rank' ? look.color : (O.trim as string);
    const acc = accessoriesOf(O, look.seed);
    accBack(ctx, d, O, acc);
    if (O.style === 'marine') marineBody(ctx, d, O, trim, acc.has('bigPads'));
    else if (O.style === 'flak') flakBody(ctx, d, O, trim, acc);
    else reconBody(ctx, d, O, trim, acc);
    accBody(ctx, d, O, trim, acc);
    if (O.head === 'helmet') marineHelmet(ctx, d, O, trim, hx);
    else if (O.head === 'beret' || O.head === 'cadet') {
      // Глава восстания: броня как у OTA, но без шлема — лицо, короткая стрижка, красный берет; курсант — пилотка.
      headPath(ctx, d, hx);
      ctx.fillStyle = skin;
      ctx.fill();
      ctx.save();
      headPath(ctx, d, hx);
      ctx.clip();
      ctx.fillStyle = PAWN.shade;
      ctx.fillRect(d === 'E' ? hx - 20 - 2 : 3, -40, 20, 60);
      ctx.restore();
      headPath(ctx, d, hx);
      stroke(ctx, PAWN.outlineWidth);
      if (d !== 'N') face(ctx, d, hx);
      frontHair(ctx, d, 'short', hair, hx);
      // Курсант академии — лицо открыто, пилотка.
      if (O.head === 'cadet') cap(ctx, d, O.cap as string, hx);
      else beret(ctx, d, O.beret as string, hx);
    }
    else if (O.head === 'recon') reconHelmet(ctx, d, O, trim, hx);
    else {
      gasMaskHead(ctx, d, hx);
      if (O.head === 'peaked') peakedCap(ctx, d, trim, hx);
      else flakHelmet(ctx, d, trim, hx);
    }
    accTop(ctx, d, acc);
    ctx.restore();
    return;
  }
  // Армия сопротивления и HYDRA: военная экипировка (pawnTactical).
  if (!look.clothes && O.style === 'tactical') {
    const trim = (O.armband as string | undefined) ?? PAWN.tactical.lambda;
    const acc = accessoriesOf(O, look.seed);
    accBack(ctx, d, O, acc);
    tacticalBody(ctx, d, O, look.seed);
    accBody(ctx, d, O, trim, acc);
    professionBody(ctx, d, O);
    const f = tacticalFace(O, look.seed);
    if (f === 'gasmask') gasMaskS10(ctx, d, O, hx);
    else if (f === 'balaclava') {
      balaclava(ctx, d, skin, O.mask as string, hx);
      if (d !== 'N') face(ctx, d, hx);
    } else {
      headPath(ctx, d, hx);
      ctx.fillStyle = skin;
      ctx.fill();
      ctx.save();
      headPath(ctx, d, hx);
      ctx.clip();
      ctx.fillStyle = PAWN.shade;
      ctx.fillRect(d === 'E' ? hx - 20 - 2 : 3, -40, 20, 60);
      ctx.restore();
      headPath(ctx, d, hx);
      stroke(ctx, PAWN.outlineWidth);
      if (d !== 'N') face(ctx, d, hx);
      frontHair(ctx, d, O.head === 'helmet' ? 'bald' : 'short', hair, hx);
    }
    if (O.goggles && d !== 'N') goggles(ctx, d, O.goggles as string, hx);
    if (O.head === 'helmet') michHelmet(ctx, d, O, hx, look.seed);
    else if (O.head === 'cap') cap(ctx, d, O.cap as string, hx);
    accTop(ctx, d, acc);
    ctx.restore();
    return;
  }
  if (O.style === 'cremator') {
    cremator(ctx, d, O);
    ctx.restore();
    return;
  }

  // Комплект одежды по достатку: свой рисунок туловища и головного убора (pawnClothes).
  const C = look.clothes;
  if (C) {
    const hairOn = !hidesHair(C);
    if (hairOn && d !== 'N') backHair(ctx, d, style, hair, hx);
    if (hairOn && style === 'bun' && !C.hat) bun(ctx, hair, hx);
    clothedBody(ctx, d, C, skin, look.band);
    // Надетый бронежилет — поверх одежды (пластины внутри контура туловища и наплечники).
    if (look.vest) {
      ctx.save();
      bodyPath(ctx, d);
      ctx.clip();
      clothes(ctx, d, O, C.topColor, look.vest, true);
      ctx.restore();
      bodyPath(ctx, d);
      stroke(ctx, PAWN.outlineWidth);
      shoulderPads(ctx, d, look.vest);
    }
    headPath(ctx, d, hx);
    ctx.fillStyle = skin;
    ctx.fill();
    ctx.save();
    headPath(ctx, d, hx);
    ctx.clip();
    ctx.fillStyle = PAWN.shade;
    ctx.fillRect(d === 'E' ? hx - 20 - 2 : 3, -40, 20, 60);
    ctx.restore();
    headPath(ctx, d, hx);
    stroke(ctx, PAWN.outlineWidth);
    if (d !== 'N') face(ctx, d, hx);
    if (hairOn) frontHair(ctx, d, style, hair, hx);
    // Шлем — вместо головного убора.
    clothesHead(ctx, d, C, hx, !look.helmet);
    if (look.helmet) michHelmet(ctx, d, { helmet: look.helmet }, hx, look.seed);
    ctx.restore();
    return;
  }

  // Сзади: длинные волосы и пучок.
  if (hairy && d !== 'N') backHair(ctx, d, style, hair, hx);
  if (hairy && style === 'bun') bun(ctx, hair, hx);

  // Туловище, одежда, броня.
  bodyPath(ctx, d);
  ctx.fillStyle = base;
  ctx.fill();
  ctx.save();
  ctx.clip();
  ctx.fillStyle = PAWN.shade;
  ctx.fillRect(d === 'E' ? -1 : 2.5, -20, 20, 40);
  clothes(ctx, d, O, base, armor, vest);
  ctx.restore();
  bodyPath(ctx, d);
  stroke(ctx, PAWN.outlineWidth);
  if (vest && armor) shoulderPads(ctx, d, armor);
  professionBody(ctx, d, O);

  // Голова (у HYDRA — чёрная балаклава вместо лица).
  const masked = head === 'respirator';
  headPath(ctx, d, hx);
  ctx.fillStyle = masked ? (O.mask as string) : skin;
  ctx.fill();
  ctx.save();
  headPath(ctx, d, hx);
  ctx.clip();
  ctx.fillStyle = PAWN.shade;
  ctx.fillRect(d === 'E' ? hx - 20 - 2 : 3, -40, 20, 60);
  ctx.restore();
  headPath(ctx, d, hx);
  stroke(ctx, PAWN.outlineWidth);

  // Лицо, причёска, головной убор.
  if (d !== 'N' && !masked) face(ctx, d, hx);
  if (hairy) frontHair(ctx, d, style, hair, hx);
  if (masked) respirator(ctx, d, O, hx);
  if (head === 'beret') beret(ctx, d, O.beret as string, hx);
  if (O.facemask && d !== 'N') faceMask(ctx, d, O.facemask as string, hx);
  if (head === 'bandana') bandana(ctx, d, O.cloth as string, hx);
  if (head === 'cap') cap(ctx, d, O.cap as string, hx);
  if (head === 'chef') chefHat(ctx, d, O.chef as string, hx);
  if (head === 'hood') hood(ctx, d, O.hood as string, hx);
  if (O.goggles && d !== 'N') goggles(ctx, d, O.goggles as string, hx);
  if (look.helmet) michHelmet(ctx, d, { helmet: look.helmet }, hx, look.seed);
  if (O.convict) convict(ctx, d, O);
  ctx.restore();
}

/** Балаклава у части ветеранов и медиков — по внешности (тот же жребий, что прежде у экипировки). */
function maskRoll(seed: number): number {
  return ((Math.imul(seed ^ 0x5bd1e995, 2654435761) >>> 0) % 1000) / 1000;
}

const rebelKits = new Map<string, KitLook | null>();
/**
 * Форма стороны по умолчанию (без предметов): ВС — форма юнита по рангу, армия сопротивления и «Грозы» — экипировка
 * профессии (REBEL_KITS; балаклава — по внешности); у остальных — нет.
 */
export function defaultKit(faction: FactionId, rank: number, profession: ProfessionId | null | undefined, seed: number): KitLook | null {
  if (faction === 'cp') return unitKit(cpUnit(rank).unit);
  if (faction !== 'rebel' || !profession || !REBEL_KITS[profession]) return null;
  const ids = rebelKitIds(profession, maskRoll(seed), PAWN.tactical.maskChance);
  const key = ids.join('|');
  if (!rebelKits.has(key)) rebelKits.set(key, kitFrom(ids));
  return rebelKits.get(key)!;
}

/**
 * Форма пешки: явная (look.kit) или форма стороны по умолчанию (defaultKit). У Легиона и санитара — своя экипировка;
 * опер в штатском (гражданское, без look.kit) — без формы.
 */
function kitLookOf(look: PawnLook, O: Outfit): KitLook | null {
  if (look.faction === 'ota' || O.style === 'cremator') return null;
  if (look.kit !== undefined) return look.kit;
  if (look.faction === 'cp' && look.clothes) return null;
  return defaultKit(look.faction, look.rank, look.profession, look.seed);
}

/**
 * Пешка в форме по частям (config/uniforms.ts), слоями: волосы сзади → за спиной (накидка, полы шинели, ранец,
 * антенна) → гражданское из ателье, полевая форма или форменная рубаха → броня (бронежилет ВС, броня спецотряда,
 * силовая, плитник, разгрузка) → шея из ателье → шинель, нашивки и навесное → голова: силовой шлем или шлем
 * спецотряда с балаклавой, иначе противогаз, S10, балаклава или лицо (очки), сверху убор (каска, шлем MICH, фуражка,
 * пилотка, кепи, берет; без них — шляпа из ателье) → поверх головы сзади. Нашивки и навесное — у того, кто выглядит
 * стражником (PAWN.cpUnits.acc по юниту) или бойцом сопротивления (PAWN.professionOutfits: молния, повязка
 * «Грозы», патронташ, рация, подсумки, сумка медика).
 */
function kitPawn(ctx: Ctx, d: PawnDir, look: PawnLook, K: KitLook, fallback: string, skin: string, hair: string, style: HairStyle, hx: number): void {
  const C = look.clothes ?? null;
  const civil = !!C && !C.bare;
  const cp = look.faction === 'cp';
  const prof = look.faction === 'rebel' && look.profession ? PAWN.professionOutfits[look.profession] : undefined;
  const army = !!prof && (prof.style === 'tactical' || prof.style === 'marine') ? prof : undefined;
  const trim = K.trim ?? (cp ? look.color : army ? ((army.armband as string | undefined) ?? PAWN.tactical.lambda) : PAWN.gear.trim);
  const acc = cp ? accessoriesOf(PAWN.cpUnits[cpUnit(look.rank).unit], look.seed) : army ? accessoriesOf(army, look.seed) : new Set<string>();
  // Шинель, накидка и ранец — вещи, а не навесное юнита.
  for (const a of ['coat', 'cape', 'pack']) acc.delete(a);
  if (K.coat === 'greatcoat') acc.add('coat');
  if (K.coat === 'cape') acc.add('cape');
  if (K.pack && K.armor !== 'marine') acc.add('pack');
  const shirt = K.shirt ?? (cp ? (PAWN.outfits.cp.base as string) : fallback);
  const O: Outfit = {
    style: K.armor === 'marine' ? 'marine' : 'kit',
    base: shirt,
    armor: K.armorColor ?? PAWN.gear.reconArmor,
    flak: K.armorColor ?? PAWN.gear.flak,
    vest: K.armor === 'flak',
    belt: K.belt ?? (PAWN.outfits.cp.belt as string),
    coat: K.coatColor ?? '#1f2328',
    cape: K.coatColor ?? '#6e1414',
    helmet: K.headColor ?? PAWN.gear.helmet,
    visor: K.visor ?? PAWN.gear.reconVisor,
    shine: K.shine ?? PAWN.gear.shine,
    eye: K.eye ?? PAWN.gear.reconGlow,
    eyes: K.eyes ?? 1,
  };
  if (K.packColor) O.packColor = K.packColor;
  // Лицо и причёска: шлем на всю голову, маска, кепи и фуражка (коротко стрижен), шлем MICH и каска (под ними не видно).
  const fullHelmet = K.head === 'recon' || K.head === 'marine';
  const masked = K.face === 'gas' || K.face === 's10' || K.face === 'balaclava';
  const hairStyle: HairStyle = K.head === 'flak' || K.head === 'mich' ? 'bald' : K.head === 'peaked' || K.head === 'cadet' || K.head === 'fieldcap' || K.head === 'beret' ? 'short' : style;
  const hairOn = !fullHelmet && !masked && !(C && hidesHair(C));
  if (hairOn && !K.head && d !== 'N') backHair(ctx, d, hairStyle, hair, hx);
  if (hairOn && !K.head && hairStyle === 'bun' && !C?.hat) bun(ctx, hair, hx);
  accBack(ctx, d, O, acc);
  // Низ: гражданское, полевая форма или рубаха (у формы ВС без своей одежды — одним проходом с бронёй, как прежде).
  const own = !civil && !K.fatigues;
  const tactical = K.armor === 'plate' || K.armor === 'chest';
  if (civil) clothedBody(ctx, d, C!, skin, look.band);
  else if (K.fatigues) tacticalBody(ctx, d, { base: K.fatigues, camo: K.camo ?? '', belt: K.belt ?? PAWN.tactical.belt, lambda: army?.lambda ?? false }, look.seed);
  else if (!K.armor || tactical) flakBody(ctx, d, { ...O, vest: false }, trim, acc);
  const over: Outfit = own ? O : { ...O, base: '' };
  if (!own) delete over.base;
  if (K.armor === 'marine') marineBody(ctx, d, over, trim, acc.has('bigPads'));
  else if (K.armor === 'recon') reconBody(ctx, d, over, trim, acc);
  else if (K.armor === 'flak') flakBody(ctx, d, own ? O : { ...over, vest: true }, trim, acc);
  else if (tactical) tacticalBody(ctx, d, { rig: K.armor!, rigColor: K.armorColor ?? '#4a5234' }, look.seed);
  // Бронежилет не из формы (снаряжение) — пластины поверх.
  if (!K.armor && look.vest) {
    ctx.save();
    bodyPath(ctx, d);
    ctx.clip();
    clothes(ctx, d, O, shirt, look.vest, true);
    ctx.restore();
    bodyPath(ctx, d);
    stroke(ctx, PAWN.outlineWidth);
    shoulderPads(ctx, d, look.vest);
  }
  if (C?.bare) clothesNeck(ctx, d, C);
  accBody(ctx, d, O, trim, acc);
  if (army) professionBody(ctx, d, { bandolier: army.bandolier ?? false, nade: army.nade ?? false, armband: army.armband ?? false });
  if (K.head === 'marine') marineHelmet(ctx, d, O, trim, hx);
  else if (K.head === 'recon') reconHelmet(ctx, d, { armor: O.helmet }, trim, hx);
  else {
    if (K.face === 'gas') gasMaskHead(ctx, d, hx);
    else if (K.face === 's10') gasMaskS10(ctx, d, { mask: K.maskColor ?? '#17181a', lens: K.lens ?? '#2c3a46', filter: K.filter ?? '#232629', filterRing: K.filterRing ?? '#4d86b8' }, hx);
    else if (K.face === 'balaclava') {
      balaclava(ctx, d, skin, K.maskColor ?? '#3a3a30', hx);
      if (d !== 'N') face(ctx, d, hx);
    } else {
      headPath(ctx, d, hx);
      ctx.fillStyle = skin;
      ctx.fill();
      ctx.save();
      headPath(ctx, d, hx);
      ctx.clip();
      ctx.fillStyle = PAWN.shade;
      ctx.fillRect(d === 'E' ? hx - 20 - 2 : 3, -40, 20, 60);
      ctx.restore();
      headPath(ctx, d, hx);
      stroke(ctx, PAWN.outlineWidth);
      if (d !== 'N') face(ctx, d, hx);
      if (hairOn) frontHair(ctx, d, hairStyle, hair, hx);
    }
    if (K.face === 'goggles' && d !== 'N') goggles(ctx, d, K.goggles ?? '#ff8a3a', hx);
    // Из ателье: убор (если формы на голове нет), платок на лице и очки (не поверх маски).
    if (C && !masked) clothesHead(ctx, d, C, hx, !K.head);
    else if (C && !K.head) clothesHead(ctx, d, { ...C, neck: undefined, glasses: false }, hx, true);
    if (K.head === 'flak') flakHelmet(ctx, d, trim, hx);
    else if (K.head === 'peaked') peakedCap(ctx, d, trim, hx);
    else if (K.head === 'cadet' || K.head === 'fieldcap') cap(ctx, d, O.helmet as string, hx);
    else if (K.head === 'beret') beret(ctx, d, O.helmet as string, hx);
    else if (K.head === 'mich') michHelmet(ctx, d, { helmet: O.helmet, helmetCamo: !!K.headCamo, camo: K.headCamo ?? '', hgoggles: K.hgoggles ?? false, nvg: !!K.nvg }, hx, look.seed);
    else if (look.helmet) michHelmet(ctx, d, { helmet: look.helmet }, hx, look.seed);
  }
  accTop(ctx, d, acc);
}

/** Поднадзорный: номер на робе (спереди и на спине) и ошейник-маячок с огоньком. */
function convict(ctx: Ctx, d: PawnDir, O: Outfit): void {
  const B = PAWN.body;
  const side = d === 'E';
  if (!side) {
    // Белая нашивка с номером: полоски «цифр».
    const y = B.top + 5;
    ctx.beginPath();
    ctx.rect(-3.4, y, 6.8, 3.4);
    fillStroke(ctx, O.number as string, 0.6);
    ctx.fillStyle = PAWN.outline;
    for (let k = 0; k < 3; k++) ctx.fillRect(-2.5 + k * 1.9, y + 0.9, 1.1, 1.6);
  }
  ctx.beginPath();
  ctx.ellipse(side ? 1 : 0, B.top + 1.6, side ? 3.8 : 4.6, 1.5, 0, 0, Math.PI * 2);
  fillStroke(ctx, O.band as string, PAWN.outlineWidth * 0.8);
  if (d !== 'N') {
    ctx.beginPath();
    ctx.arc(side ? 4.2 : 0, B.top + 2.1, 0.8, 0, Math.PI * 2);
    ctx.fillStyle = O.light as string;
    ctx.fill();
  }
}




/** Одежда под бронёй и сама броня (внутри контура туловища — клип уже стоит). */
function clothes(ctx: Ctx, d: PawnDir, O: Record<string, unknown>, base: string, armor: string | undefined, vest: boolean): void {
  const top = PAWN.body.top;
  const side = d === 'E';
  if (!vest) {
    // Гражданская одежда: воротник, молния, карман; ТС — повязка; комендант — костюм.
    if (d === 'S') {
      if (O.collar) {
        ctx.beginPath();
        ctx.moveTo(-3.6, top);
        ctx.lineTo(0, top + 3.6);
        ctx.lineTo(3.6, top);
        fillStroke(ctx, O.collar as string);
      }
      if (O.tie) {
        ctx.beginPath();
        ctx.moveTo(-0.9, top + 2.4);
        ctx.lineTo(0.9, top + 2.4);
        ctx.lineTo(1.2, top + 8);
        ctx.lineTo(0, top + 9.2);
        ctx.lineTo(-1.2, top + 8);
        ctx.closePath();
        fillStroke(ctx, O.tie as string);
        // Лацканы.
        ctx.beginPath();
        ctx.moveTo(-3.6, top);
        ctx.lineTo(-1.6, top + 8);
        ctx.moveTo(3.6, top);
        ctx.lineTo(1.6, top + 8);
        stroke(ctx, PAWN.seamWidth);
      }
      if (O.zip) {
        ctx.beginPath();
        ctx.moveTo(0, top + 3.6);
        ctx.lineTo(0, PAWN.body.bottom);
        stroke(ctx, 0.6, tint(base, -0.45));
        ctx.beginPath();
        ctx.rect(-5.4, top + 5.5, 3.2, 2.6);
        fillStroke(ctx, tint(base, -0.12), 0.6);
      }
    } else if (side) {
      ctx.beginPath();
      ctx.moveTo(-1, PAWN.body.top + 8);
      ctx.lineTo(6, PAWN.body.top + 8);
      stroke(ctx, 0.6, tint(base, -0.35));
    }
    // Пояс брюк.
    ctx.beginPath();
    ctx.rect(-12, 7.2, 24, 1.6);
    fillStroke(ctx, tint(base, -0.35), 0.6);
    if (O.armband && d !== 'N') {
      ctx.beginPath();
      ctx.rect(side ? -3 : 4.2, top + 3.2, side ? 5 : 4, 2);
      fillStroke(ctx, O.armband as string, 0.6);
    }
    return;
  }
  if (!armor) return;
  const belt = (O.belt as string) ?? '#2a2a2a';
  const hi = tint(armor, 0.28);
  // Нагрудная пластина с вырезом у горла (спереди), спинная (сзади), половина (в профиле).
  ctx.beginPath();
  if (d === 'S') {
    ctx.moveTo(-5.8, top + 2.6);
    ctx.lineTo(-2.2, top + 1.4);
    ctx.lineTo(0, top + 3.6);
    ctx.lineTo(2.2, top + 1.4);
    ctx.lineTo(5.8, top + 2.6);
    ctx.lineTo(6.2, 6.4);
    ctx.lineTo(-6.2, 6.4);
  } else if (d === 'N') {
    ctx.moveTo(-6, top + 1.6);
    ctx.lineTo(6, top + 1.6);
    ctx.lineTo(6.4, 6.4);
    ctx.lineTo(-6.4, 6.4);
  } else {
    ctx.moveTo(-1.5, top + 1.4);
    ctx.lineTo(6, top + 2.4);
    ctx.lineTo(7.2, 6.4);
    ctx.lineTo(-1.8, 6.4);
  }
  ctx.closePath();
  fillStroke(ctx, armor);
  // Блик по верхнему краю пластины.
  ctx.beginPath();
  if (d === 'S') {
    ctx.moveTo(-5, top + 3.4);
    ctx.lineTo(-2.2, top + 2.5);
    ctx.moveTo(2.2, top + 2.5);
    ctx.lineTo(5, top + 3.4);
  } else if (d === 'N') {
    ctx.moveTo(-5.2, top + 2.5);
    ctx.lineTo(5.2, top + 2.5);
  } else {
    ctx.moveTo(-0.8, top + 2.3);
    ctx.lineTo(5.4, top + 3.1);
  }
  stroke(ctx, 0.9, hi);
  // Центральный щиток (спереди) / ребро (сзади).
  if (d === 'S') {
    ctx.beginPath();
    ctx.rect(-2.3, top + 5.4, 4.6, 4.6);
    fillStroke(ctx, tint(armor, -0.22));
    ctx.beginPath();
    ctx.moveTo(-1.5, top + 6.3);
    ctx.lineTo(1.5, top + 6.3);
    stroke(ctx, 0.6, hi);
  } else if (d === 'N') {
    ctx.beginPath();
    ctx.moveTo(0, top + 2.4);
    ctx.lineTo(0, 6);
    stroke(ctx, PAWN.seamWidth);
  } else {
    ctx.beginPath();
    ctx.rect(2.5, top + 5.4, 3.6, 4.2);
    fillStroke(ctx, tint(armor, -0.22));
  }
  // Пояс с пряжкой.
  ctx.beginPath();
  ctx.rect(-12, 6.4, 24, 2.4);
  fillStroke(ctx, belt);
  if (d !== 'N') {
    ctx.beginPath();
    ctx.rect(side ? 4 : -1.3, 6.7, 2.6, 1.8);
    fillStroke(ctx, '#8d9299', 0.5);
  }
  // Набедренник/подсумки.
  ctx.beginPath();
  if (d === 'S') {
    ctx.moveTo(-4.8, 8.8);
    ctx.lineTo(4.8, 8.8);
    ctx.lineTo(4.2, 12.6);
    ctx.quadraticCurveTo(0, 14.4, -4.2, 12.6);
  } else if (d === 'N') {
    ctx.moveTo(-5.4, 8.8);
    ctx.lineTo(5.4, 8.8);
    ctx.lineTo(4.8, 11.2);
    ctx.lineTo(-4.8, 11.2);
  } else {
    ctx.moveTo(0.5, 8.8);
    ctx.lineTo(6.8, 8.8);
    ctx.lineTo(6, 12.8);
    ctx.lineTo(1, 12.8);
  }
  ctx.closePath();
  fillStroke(ctx, tint(armor, -0.12));
  ctx.beginPath();
  if (d === 'S') ctx.rect(-2.2, 9.6, 4.4, 2.6);
  else if (d === 'N') ctx.rect(-6.5, 8.9, 3, 2.4);
  else ctx.rect(2, 9.6, 3.4, 2.4);
  fillStroke(ctx, tint(armor, -0.3));
}

/** Наплечники поверх контура туловища (как у брони RimWorld). */
function shoulderPads(ctx: Ctx, d: PawnDir, armor: string): void {
  const top = PAWN.body.top;
  const pads = d === 'E' ? [0.6] : [-PAWN.body.shoulder + 0.4, PAWN.body.shoulder - 0.4];
  for (const px of pads) {
    ctx.beginPath();
    ctx.ellipse(px, top + 2.2, 3.3, 3, 0, 0, Math.PI * 2);
    ctx.fillStyle = armor;
    ctx.fill();
    stroke(ctx, PAWN.outlineWidth * 0.85);
    ctx.beginPath();
    ctx.arc(px, top + 2.2, 1.9, Math.PI * 1.1, Math.PI * 1.75);
    stroke(ctx, 0.8, tint(armor, 0.32));
  }
}


/** Глаза с тяжёлыми веками и рот (как у пешек RimWorld). */
/** Лицо текущей пешки (ставит drawPawn): внешность и мимика — чтобы не тянуть их через все ветки одежды. */
const faceOf = { seed: 0, hair: '#000', style: 'short' as HairStyle, blink: false, talk: false };

/** Доля 0..1 из зерна внешности (свой сдвиг на каждую черту). */
function trait(seed: number, shift: number): number {
  return (((seed >>> shift) ^ (seed * 2654435761)) >>> 0) % 1000 / 1000;
}

/** Затемнить цвет #rrggbb на долю k. */
function darken(hex: string, k: number): string {
  const n = parseInt(hex.slice(1, 7), 16);
  const f = (v: number) => Math.round(v * (1 - k));
  return `rgb(${f(n >> 16)},${f((n >> 8) & 255)},${f(n & 255)})`;
}

function face(ctx: Ctx, d: PawnDir, hx: number): void {
  const E = PAWN.eye;
  const F = PAWN.face;
  const H = PAWN.head;
  const seed = faceOf.seed;
  const side = d === 'E';
  const eyes = side ? [hx + H.r - 2.4] : [-E.dx, E.dx];
  // Щетина — по нижней части лица (коротко стриженые и лысые).
  const shortHair = faceOf.style === 'short' || faceOf.style === 'bald' || faceOf.style === 'messy';
  if (shortHair && trait(seed, 3) < F.stubble.share) {
    ctx.save();
    headPath(ctx, d, hx);
    ctx.clip();
    ctx.fillStyle = F.stubble.color;
    ctx.fillRect(side ? hx - 1 : -H.r, F.stubble.from, H.r * 2 + 2, H.r + 4);
    ctx.restore();
  }
  // Румянец и тень скул.
  const cheeks = side ? [hx + F.blush.x - 1.6] : [-F.blush.x, F.blush.x];
  for (const cx of cheeks) {
    ctx.beginPath();
    ctx.ellipse(cx, F.blush.y, F.blush.rx, F.blush.ry, 0, 0, Math.PI * 2);
    ctx.fillStyle = F.blush.color;
    ctx.fill();
  }
  ctx.strokeStyle = F.cheek.color;
  ctx.lineWidth = F.cheek.w;
  ctx.beginPath();
  if (side) {
    ctx.moveTo(hx + 1.2, -8.2);
    ctx.quadraticCurveTo(hx + 2.4, -6.4, hx + 4.2, -5.6);
  } else {
    ctx.moveTo(-5.9, -8.4);
    ctx.quadraticCurveTo(-5.3, -6.6, -4.1, -5.7);
    ctx.moveTo(5.9, -8.4);
    ctx.quadraticCurveTo(5.3, -6.6, 4.1, -5.7);
  }
  ctx.stroke();
  // Веснушки.
  if (trait(seed, 9) < F.freckles.share) {
    ctx.fillStyle = F.freckles.color;
    for (const [fx, fy] of side ? [[hx + 3.2, -7.6], [hx + 4.1, -7.1], [hx + 3.6, -6.6]] : [[-3.8, -7.7], [-2.9, -7.2], [-4.4, -7], [3.8, -7.7], [2.9, -7.2], [4.4, -7]]) {
      ctx.fillRect(fx - 0.25, fy - 0.25, 0.5, 0.5);
    }
  }
  // Тень носа (спереди; в профиль нос — в контуре головы).
  if (!side) {
    ctx.beginPath();
    ctx.moveTo(0.3, -8.4);
    ctx.quadraticCurveTo(1, -7.1, 0.1, -6.7);
    ctx.strokeStyle = F.nose.color;
    ctx.lineWidth = 0.6;
    ctx.stroke();
  }
  // Глаза: открыты — зрачок, веко, блик; закрыты — дуга.
  for (const ex of eyes) {
    if (faceOf.blink) {
      ctx.beginPath();
      ctx.moveTo(ex - E.rx - 0.3, E.y);
      ctx.quadraticCurveTo(ex, E.y + 0.7, ex + E.rx + 0.3, E.y);
      stroke(ctx, 0.75);
    } else {
      ctx.beginPath();
      ctx.ellipse(ex, E.y, E.rx, E.ry, 0, 0, Math.PI * 2);
      ctx.fillStyle = E.color;
      ctx.fill();
      ctx.beginPath();
      ctx.moveTo(ex - E.rx - 0.5, E.y - E.ry * E.lid);
      ctx.lineTo(ex + E.rx + 0.5, E.y - E.ry * E.lid);
      stroke(ctx, 0.8);
      ctx.beginPath();
      ctx.arc(ex + F.shine.dx, E.y + F.shine.dy, F.shine.r, 0, Math.PI * 2);
      ctx.fillStyle = F.shine.color;
      ctx.fill();
    }
    // Морщинки у внешнего угла глаза.
    if (trait(seed, 13) < F.wrinkles) {
      const out = side || ex > 0 ? 1 : -1;
      ctx.beginPath();
      ctx.moveTo(ex + out * (E.rx + 0.6), E.y - 0.3);
      ctx.lineTo(ex + out * (E.rx + 1.4), E.y - 0.6);
      ctx.moveTo(ex + out * (E.rx + 0.6), E.y + 0.3);
      ctx.lineTo(ex + out * (E.rx + 1.4), E.y + 0.6);
      ctx.strokeStyle = F.cheek.color;
      ctx.lineWidth = 0.45;
      ctx.stroke();
    }
    // Брови цвета волос: наклон и толщина — по внешности (лысому — светлее).
    const B = F.brow;
    const tilt = (trait(seed, 5) - B.calm) * 2 * B.tilt;
    const inner = side ? -1 : ex > 0 ? -1 : 1;
    ctx.beginPath();
    ctx.moveTo(ex - inner * B.len / 2, B.y + 0.15);
    ctx.lineTo(ex + inner * B.len / 2, B.y - tilt);
    ctx.strokeStyle = darken(faceOf.hair, faceOf.style === 'bald' ? 0.1 : B.dark);
    ctx.lineWidth = B.w + trait(seed, 7) * 0.3;
    ctx.stroke();
  }
  // Рот: говорит — открыт, иначе по складу лица (ровно, улыбка, прямо, хмуро).
  const M = PAWN.mouth;
  if (faceOf.talk) {
    ctx.beginPath();
    if (side) ctx.ellipse(hx + H.r - 1.6, M.y + 0.1, 0.7, 0.6, 0, 0, Math.PI * 2);
    else ctx.ellipse(0, M.y + 0.15, M.w * 0.45, 0.65, 0, 0, Math.PI * 2);
    ctx.fillStyle = F.open;
    ctx.fill();
    stroke(ctx, 0.5);
    return;
  }
  let r = trait(seed, 11);
  let mood = 0;
  while (mood < F.moods.length - 1 && r >= F.moods[mood]) r -= F.moods[mood++];
  ctx.beginPath();
  if (side) {
    const lift = mood === 1 ? -0.5 : mood === 3 ? 0.4 : 0;
    ctx.moveTo(hx + H.r - 2.6, M.y);
    ctx.lineTo(hx + H.r - 0.9, M.y - 0.2 + lift);
  } else {
    const bend = mood === 0 ? 0.35 : mood === 1 ? 0.8 : mood === 2 ? 0 : -0.55;
    ctx.moveTo(-M.w / 2 - (mood === 1 ? 0.2 : 0), M.y);
    ctx.quadraticCurveTo(0, M.y + bend, M.w / 2 + (mood === 1 ? 0.2 : 0), M.y);
  }
  stroke(ctx, 0.7);
  // Нижняя губа — лёгкий штрих.
  if (!side) {
    ctx.beginPath();
    ctx.moveTo(-0.45, M.y + 0.9);
    ctx.lineTo(0.45, M.y + 0.9);
    ctx.strokeStyle = F.lips;
    ctx.globalAlpha *= 0.45;
    ctx.lineWidth = 0.5;
    ctx.stroke();
    ctx.globalAlpha /= 0.45;
  }
}

/** Длинные волосы за головой (на плечи). */
function backHair(ctx: Ctx, d: PawnDir, style: HairStyle, hair: string, hx: number): void {
  if (style !== 'long' && style !== 'messy') return;
  const H = PAWN.head;
  const long = style === 'long';
  ctx.beginPath();
  if (d === 'E') {
    ctx.moveTo(hx - 1, H.y - H.r);
    ctx.quadraticCurveTo(hx - H.r - 3, H.y - 2, hx - H.r - 1.5, H.y + (long ? 10 : 5));
    ctx.lineTo(hx - 2, H.y + (long ? 8 : 4));
  } else {
    const w = H.r + (long ? 2.4 : 1.6);
    ctx.moveTo(-w, H.y);
    ctx.lineTo(-w + 0.5, H.y + (long ? 10.5 : 6));
    ctx.lineTo(-w + 3, H.y + (long ? 9 : 5));
    ctx.lineTo(w - 3, H.y + (long ? 9 : 5));
    ctx.lineTo(w - 0.5, H.y + (long ? 10.5 : 6));
    ctx.lineTo(w, H.y);
  }
  ctx.closePath();
  ctx.fillStyle = tint(hairHex(hair), -0.15);
  ctx.fill();
  stroke(ctx, PAWN.outlineWidth);
}

function hairHex(c: string): string {
  return c.startsWith('#') ? c : '#555555';
}

function bun(ctx: Ctx, hair: string, hx: number): void {
  const H = PAWN.head;
  ctx.beginPath();
  ctx.arc(hx - 0.5, H.y - H.r - 1.6, 3.2, 0, Math.PI * 2);
  ctx.fillStyle = hair;
  ctx.fill();
  stroke(ctx, PAWN.outlineWidth);
}

/**
 * Причёска спереди: объём шире головы, неровный край; лохматая — с прядями-чёлкой на лоб;
 * длинная — пряди по бокам лица. Сзади — затылок целиком, в профиле — верх и затылок.
 */
function frontHair(ctx: Ctx, d: PawnDir, style: HairStyle, hair: string, hx: number): void {
  if (style === 'bald') return;
  const H = PAWN.head;
  const r = H.r;
  const cy = H.y;
  const vol = style === 'messy' ? 1.8 : 0.9;
  ctx.beginPath();
  if (d === 'N') {
    const w = r + vol;
    const low = style === 'long' ? cy + r + 3 : cy + r * 0.55;
    ctx.moveTo(-w, cy + 1);
    ctx.bezierCurveTo(-w, cy - r - vol * 1.6, w, cy - r - vol * 1.6, w, cy + 1);
    ctx.lineTo(w - 0.8, low);
    ctx.lineTo(w * 0.35, low - 1.6);
    ctx.lineTo(0, low + 0.6);
    ctx.lineTo(-w * 0.35, low - 1.6);
    ctx.lineTo(-w + 0.8, low);
  } else if (d === 'E') {
    const back = style === 'long' ? cy + 8 : cy + 2.5;
    ctx.moveTo(hx + r - 1, cy - 3.6);
    ctx.bezierCurveTo(hx + r + 0.5, cy - r - vol * 1.2, hx - r - vol, cy - r - vol * 1.4, hx - r - vol, cy + 1);
    ctx.lineTo(hx - r - vol + 0.6, back);
    ctx.lineTo(hx - r + 3, back - 1.2);
    ctx.lineTo(hx - 1.5, cy - 1.8);
    ctx.lineTo(hx + 1.5, cy - 3.2);
    if (style === 'messy') {
      ctx.lineTo(hx + 3.5, cy - 1.2);
      ctx.lineTo(hx + 4.4, cy - 3.6);
      ctx.lineTo(hx + r - 0.2, cy - 1.8);
    }
  } else {
    const w = r + vol;
    const side = style === 'long' ? cy + 7.5 : style === 'messy' ? cy + 2.5 : cy - 0.5;
    ctx.moveTo(-w, side);
    ctx.bezierCurveTo(-w - 0.4, cy - r - vol * 1.8, w + 0.4, cy - r - vol * 1.8, w, side);
    if (style === 'messy') {
      // Чёлка прядями.
      ctx.lineTo(w - 1.8, cy - 1);
      ctx.lineTo(3.8, cy - 0.4);
      ctx.lineTo(2.8, cy - 3.4);
      ctx.lineTo(0.6, cy - 1.2);
      ctx.lineTo(-1, cy - 3.8);
      ctx.lineTo(-3.4, cy - 0.8);
      ctx.lineTo(-4.4, cy - 3.4);
      ctx.lineTo(-w + 1.8, cy - 1);
    } else if (style === 'long') {
      ctx.lineTo(w - 2, side - 0.5);
      ctx.lineTo(r - 2, cy - 3.2);
      ctx.lineTo(1.5, cy - 4.2);
      ctx.lineTo(-1.5, cy - 3.6);
      ctx.lineTo(-r + 2, cy - 3.2);
      ctx.lineTo(-w + 2, side - 0.5);
    } else {
      ctx.lineTo(r - 0.8, cy - 3.2);
      ctx.lineTo(2.4, cy - 4.4);
      ctx.lineTo(0.2, cy - 3.6);
      ctx.lineTo(-2.2, cy - 4.5);
      ctx.lineTo(-r + 0.8, cy - 3.2);
    }
  }
  ctx.closePath();
  ctx.fillStyle = hair;
  ctx.fill();
  stroke(ctx, PAWN.outlineWidth);
  // Пряди — тёмные штрихи.
  ctx.beginPath();
  if (d === 'N') {
    ctx.moveTo(-2, cy - r + 1);
    ctx.quadraticCurveTo(-3, cy, -2.2, cy + 3);
    ctx.moveTo(2.5, cy - r + 1.5);
    ctx.quadraticCurveTo(3.2, cy, 2.2, cy + 2.5);
  } else if (d === 'E') {
    ctx.moveTo(hx + 1, cy - r + 0.5);
    ctx.quadraticCurveTo(hx - 3, cy - 4, hx - r + 0.5, cy + 0.5);
  } else {
    ctx.moveTo(-1.5, cy - r);
    ctx.quadraticCurveTo(-3.5, cy - 5, -4.5, cy - 2.5);
    ctx.moveTo(2, cy - r + 0.3);
    ctx.quadraticCurveTo(3.4, cy - 5.5, 4.6, cy - 2.8);
  }
  stroke(ctx, 0.6, tint(hairHex(hair), -0.45));
}

function bandana(ctx: Ctx, d: PawnDir, cloth: string, hx: number): void {
  const H = PAWN.head;
  const cy = H.y;
  const r = H.r;
  ctx.beginPath();
  if (d === 'E') {
    ctx.moveTo(hx + r - 0.4, cy - 4.8);
    ctx.quadraticCurveTo(hx, cy - 6.6, hx - r - 0.2, cy - 3.4);
    ctx.lineTo(hx - r, cy - 1);
    ctx.quadraticCurveTo(hx, cy - 4.2, hx + r, cy - 2.4);
  } else {
    ctx.moveTo(-r - 0.3, cy - 3.2);
    ctx.quadraticCurveTo(0, cy - 7, r + 0.3, cy - 3.2);
    ctx.lineTo(r + 0.2, cy - 0.8);
    ctx.quadraticCurveTo(0, cy - 4.6, -r - 0.2, cy - 0.8);
  }
  ctx.closePath();
  fillStroke(ctx, cloth, PAWN.outlineWidth * 0.8);
  if (d !== 'S') {
    // Узел и концы сзади.
    const kx = d === 'E' ? hx - r : 0;
    const ky = d === 'E' ? cy - 2.2 : cy - 3;
    ctx.beginPath();
    ctx.moveTo(kx, ky);
    ctx.lineTo(kx - (d === 'E' ? 4 : 2), ky + 5);
    ctx.lineTo(kx - (d === 'E' ? 2 : 0.5), ky + 5.4);
    ctx.closePath();
    ctx.moveTo(kx, ky);
    ctx.lineTo(kx + (d === 'E' ? -1 : 2), ky + 5.6);
    ctx.lineTo(kx + (d === 'E' ? 0.8 : 3.4), ky + 5);
    ctx.closePath();
    fillStroke(ctx, cloth);
  }
}

function cap(ctx: Ctx, d: PawnDir, color: string, hx: number): void {
  const H = PAWN.head;
  const cy = H.y;
  const r = H.r;
  ctx.beginPath();
  if (d === 'E') {
    ctx.moveTo(hx - r - 0.6, cy - 2.4);
    ctx.bezierCurveTo(hx - r, cy - r - 2.4, hx + r, cy - r - 2.4, hx + r + 0.4, cy - 3.2);
    ctx.lineTo(hx + r + 4.2, cy - 3);
    ctx.lineTo(hx + r + 4, cy - 1.8);
    ctx.lineTo(hx - r - 0.6, cy - 1.6);
  } else {
    ctx.moveTo(-r - 0.6, cy - 2.2);
    ctx.bezierCurveTo(-r, cy - r - 2.6, r, cy - r - 2.6, r + 0.6, cy - 2.2);
    ctx.lineTo(-r - 0.6, cy - 2.2);
  }
  ctx.closePath();
  fillStroke(ctx, color, PAWN.outlineWidth);
  if (d === 'S') {
    ctx.beginPath();
    ctx.ellipse(0, cy - 2.2, r - 1, 1.4, 0, 0, Math.PI);
    fillStroke(ctx, tint(color, -0.25), PAWN.outlineWidth * 0.8);
  }
  ctx.beginPath();
  ctx.moveTo(d === 'E' ? hx - 2 : -3, cy - r + 0.5);
  ctx.quadraticCurveTo(d === 'E' ? hx + 1 : 0, cy - r - 1.2, d === 'E' ? hx + 4 : 3, cy - r + 0.5);
  stroke(ctx, 0.8, tint(color, 0.3));
}

/**
 * Силовая броня (как у пехотинцев RimWorld): тёмный комбинезон, кираса с грудными пластинами и
 * бликом, горжет, пояс с подсумками, набедренники, ранец за спиной, большие наплечники с полосой.
 */
function marineBody(ctx: Ctx, d: PawnDir, O: Record<string, unknown>, trim: string, big = false): void {
  const B = PAWN.body;
  const top = B.top;
  const armor = O.armor as string;
  const hi = tint(armor, 0.3);
  const lo = tint(armor, -0.22);
  const side = d === 'E';
  // Ранец за спиной — в профиле торчит назад.
  if (side) {
    ctx.beginPath();
    roundRect(ctx, -9.2, top + 1.4, 5, 9, 1.6);
    fillStroke(ctx, lo, PAWN.outlineWidth);
    ctx.beginPath();
    ctx.moveTo(-8.2, top + 4);
    ctx.lineTo(-5.4, top + 4);
    ctx.moveTo(-8.2, top + 6);
    ctx.lineTo(-5.4, top + 6);
    stroke(ctx, 0.6, tint(armor, -0.45));
  }
  // Комбинезон (силуэт туловища); без O.base — броня поверх уже нарисованной одежды.
  bodyPath(ctx, d);
  if (O.base) {
    ctx.fillStyle = O.base as string;
    ctx.fill();
  }
  ctx.save();
  ctx.clip();
  // Кираса.
  ctx.beginPath();
  if (d === 'S') {
    ctx.moveTo(-6.9, top + 0.6);
    ctx.lineTo(6.9, top + 0.6);
    ctx.lineTo(8.2, 5.2);
    ctx.lineTo(5.2, 7.4);
    ctx.lineTo(-5.2, 7.4);
    ctx.lineTo(-8.2, 5.2);
  } else if (d === 'N') {
    ctx.moveTo(-7.2, top + 0.4);
    ctx.lineTo(7.2, top + 0.4);
    ctx.lineTo(8.4, 7.4);
    ctx.lineTo(-8.4, 7.4);
  } else {
    ctx.moveTo(-3.6, top + 0.4);
    ctx.lineTo(4.8, top + 0.8);
    ctx.lineTo(7.4, 4.8);
    ctx.lineTo(5.6, 7.4);
    ctx.lineTo(-4.4, 7.4);
  }
  ctx.closePath();
  fillStroke(ctx, armor);
  ctx.fillStyle = PAWN.shade;
  ctx.fillRect(side ? -20 : 3, -20, side ? 18 : 20, 40);
  ctx.beginPath();
  if (d === 'S') {
    // Грудные пластины и блик.
    ctx.moveTo(0, top + 1);
    ctx.lineTo(0, 6.8);
    ctx.moveTo(-7.4, top + 6.2);
    ctx.quadraticCurveTo(-3.5, top + 7.8, 0, top + 6.8);
    ctx.quadraticCurveTo(3.5, top + 7.8, 7.4, top + 6.2);
    stroke(ctx, PAWN.seamWidth);
    ctx.beginPath();
    ctx.moveTo(-5.6, top + 2);
    ctx.lineTo(-1.2, top + 2);
    ctx.moveTo(1.2, top + 2);
    ctx.lineTo(4.2, top + 2);
    stroke(ctx, 1, hi);
    // Нашивка цвета ранга.
    ctx.beginPath();
    ctx.rect(-5.4, top + 3.4, 3, 1.4);
    fillStroke(ctx, trim, 0.5);
  } else if (d === 'N') {
    // Спина: ранец с вентиляцией.
    ctx.moveTo(-7, 6);
    ctx.lineTo(7, 6);
    stroke(ctx, PAWN.seamWidth);
    ctx.beginPath();
    roundRect(ctx, -4.6, top + 2, 9.2, 7.6, 1.6);
    fillStroke(ctx, lo);
    ctx.beginPath();
    for (let k = 0; k < 3; k++) {
      ctx.moveTo(-2.8, top + 4 + k * 1.6);
      ctx.lineTo(2.8, top + 4 + k * 1.6);
    }
    stroke(ctx, 0.6, tint(armor, -0.45));
    ctx.beginPath();
    ctx.moveTo(-3.6, top + 2.6);
    ctx.lineTo(3.6, top + 2.6);
    stroke(ctx, 0.8, hi);
  } else {
    ctx.moveTo(-3.4, top + 6.4);
    ctx.quadraticCurveTo(2, top + 7.8, 7, top + 6);
    stroke(ctx, PAWN.seamWidth);
    ctx.beginPath();
    ctx.moveTo(-1.4, top + 2);
    ctx.lineTo(4.2, top + 2.3);
    stroke(ctx, 1, hi);
    ctx.beginPath();
    ctx.rect(2.2, top + 3.4, 2.8, 1.4);
    fillStroke(ctx, trim, 0.5);
  }
  // Пояс с подсумками.
  ctx.beginPath();
  ctx.rect(-12, 7.4, 24, 2.3);
  fillStroke(ctx, O.belt as string);
  ctx.beginPath();
  const pouches = d === 'S' ? [-5.6, -2.4, 1.4] : d === 'N' ? [-4.6, 2.4] : [3.2];
  for (const px of pouches) ctx.rect(px, 7.1, 2.8, 2.9);
  fillStroke(ctx, tint(O.belt as string, 0.25), 0.6);
  // Набедренники.
  ctx.beginPath();
  if (side) roundRect(ctx, -1, 10, 7.4, 3.8, 1.4);
  else {
    roundRect(ctx, -7, 10, 6.2, 3.8, 1.4);
    roundRect(ctx, 0.8, 10, 6.2, 3.8, 1.4);
  }
  fillStroke(ctx, lo);
  ctx.beginPath();
  if (side) {
    ctx.moveTo(0, 10.9);
    ctx.lineTo(5.4, 10.9);
  } else {
    ctx.moveTo(-6, 10.9);
    ctx.lineTo(-1.8, 10.9);
    ctx.moveTo(1.8, 10.9);
    ctx.lineTo(6, 10.9);
  }
  stroke(ctx, 0.7, tint(armor, 0.1));
  ctx.restore();
  bodyPath(ctx, d);
  stroke(ctx, PAWN.outlineWidth);
  // Горжет — воротник под шлемом.
  if (d !== 'N') {
    ctx.beginPath();
    ctx.ellipse(side ? 1.2 : 0, top + 0.6, side ? 3.4 : 4.6, 1.9, 0, 0, Math.PI * 2);
    fillStroke(ctx, lo, PAWN.outlineWidth * 0.8);
  }
  // Наплечники: большие, с бликом и полосой цвета ранга.
  // Катафракт (big) — наплечники ещё крупнее.
  const out = big ? 1.6 : 0.9;
  const pads = side ? [0.4] : [-(B.shoulder + out), B.shoulder + out];
  const ry = big ? 4.7 : 4;
  for (const px of pads) {
    const rx = (side ? 4.3 : 4.2) + (big ? 0.9 : 0);
    ctx.beginPath();
    ctx.ellipse(px, top + 2.4, rx, ry, 0, 0, Math.PI * 2);
    fillStroke(ctx, armor, PAWN.outlineWidth);
    ctx.save();
    ctx.beginPath();
    ctx.ellipse(px, top + 2.4, rx, ry, 0, 0, Math.PI * 2);
    ctx.clip();
    ctx.fillStyle = trim;
    ctx.fillRect(px - 6, top + ry + 0.2, 14, 1.5);
    ctx.fillStyle = PAWN.shade;
    ctx.fillRect(px - 6, top + ry + 1.7, 14, 4);
    ctx.restore();
    ctx.beginPath();
    ctx.ellipse(px, top + 2.4, rx, ry, 0, 0, Math.PI * 2);
    stroke(ctx, PAWN.outlineWidth);
    ctx.beginPath();
    ctx.arc(px - 0.6, top + 2, 2.4, Math.PI * 1.05, Math.PI * 1.6);
    stroke(ctx, 0.9, hi);
  }
}


/** Контур закрытого шлема: крупнее головы, с нащёчниками и подбородником. */
function helmetPath(ctx: Ctx, d: PawnDir, hx: number): void {
  const H = PAWN.head;
  const r = H.r + 1.2;
  const cy = H.y - 0.3;
  ctx.beginPath();
  if (d === 'E') {
    const cx = hx + 0.3;
    ctx.moveTo(cx - r, cy + 1);
    ctx.arc(cx, cy, r, Math.PI * 1.02, Math.PI * 1.98);
    ctx.bezierCurveTo(cx + r + 1.2, cy + 1, cx + r + 1.2, cy + 4.5, cx + r - 0.4, cy + 6.4);
    ctx.lineTo(cx + 1.6, cy + r);
    ctx.bezierCurveTo(cx - 2, cy + r + 0.4, cx - r + 0.4, cy + 6, cx - r, cy + 1);
  } else {
    ctx.moveTo(-r, cy + 1);
    ctx.arc(0, cy, r, Math.PI * 1.02, Math.PI * 1.98);
    ctx.bezierCurveTo(r + 0.3, cy + 4.5, r - 1.2, cy + r - 0.4, 3.2, cy + r + 0.6);
    ctx.lineTo(-3.2, cy + r + 0.6);
    ctx.bezierCurveTo(-r + 1.2, cy + r - 0.4, -r - 0.3, cy + 4.5, -r, cy + 1);
  }
  ctx.closePath();
}

/** Закрытый шлем: гребень, наушники, тёмный визор с бликом, решётка подбородника; OTA — красный огонёк. */
function marineHelmet(ctx: Ctx, d: PawnDir, O: Record<string, unknown>, trim: string, hx: number): void {
  const H = PAWN.head;
  const r = H.r + 1.2;
  const cy = H.y - 0.3;
  const helmet = O.helmet as string;
  const hi = tint(helmet, 0.32);
  const lo = tint(helmet, -0.28);
  helmetPath(ctx, d, hx);
  ctx.fillStyle = helmet;
  ctx.fill();
  ctx.save();
  helmetPath(ctx, d, hx);
  ctx.clip();
  // Объём: затенение снизу и справа.
  ctx.fillStyle = PAWN.shade;
  ctx.fillRect(d === 'E' ? hx - 20 - 1.5 : 3.2, cy - 20, 20, 40);
  ctx.fillRect(-20, cy + 4.5, 40, 20);
  if (d === 'N') {
    // Затылок: рёбра жёсткости.
    ctx.beginPath();
    ctx.moveTo(-r, cy + 3.4);
    ctx.quadraticCurveTo(0, cy + 5.4, r, cy + 3.4);
    stroke(ctx, PAWN.seamWidth);
  } else {
    // Т-образный визор (как у шлема пехотинца RimWorld): полоса на глазах и прорезь вниз.
    ctx.beginPath();
    if (d === 'E') {
      ctx.moveTo(hx + 1, cy - 2.6);
      ctx.lineTo(hx + r + 2.2, cy - 2.6);
      ctx.lineTo(hx + r + 2.2, cy + 0.8);
      ctx.lineTo(hx + r + 1.2, cy + 0.8);
      ctx.lineTo(hx + r + 1, cy + 3.4);
      ctx.lineTo(hx + r - 0.6, cy + 3.4);
      ctx.lineTo(hx + r - 0.6, cy + 0.8);
      ctx.lineTo(hx + 1, cy + 0.8);
    } else {
      const L = -r + 1.6;
      ctx.moveTo(L + 1.2, cy - 2.6);
      ctx.lineTo(-L - 1.2, cy - 2.6);
      ctx.quadraticCurveTo(-L, cy - 2.6, -L, cy - 1.4);
      ctx.lineTo(-L, cy);
      ctx.quadraticCurveTo(-L, cy + 0.8, -L - 1, cy + 0.8);
      ctx.lineTo(1.3, cy + 0.8);
      ctx.lineTo(1.1, cy + 3.8);
      ctx.lineTo(-1.1, cy + 3.8);
      ctx.lineTo(-1.3, cy + 0.8);
      ctx.lineTo(L + 1, cy + 0.8);
      ctx.quadraticCurveTo(L, cy + 0.8, L, cy);
      ctx.lineTo(L, cy - 1.4);
      ctx.quadraticCurveTo(L, cy - 2.6, L + 1.2, cy - 2.6);
    }
    ctx.closePath();
    fillStroke(ctx, O.visor as string, PAWN.seamWidth);
    // Решётка дыхательного фильтра в светлой рамке.
    ctx.beginPath();
    if (d === 'E') roundRect(ctx, hx + r - 2.6, cy + 4.2, 3.4, 2.6, 0.8);
    else roundRect(ctx, -2.9, cy + 4.5, 5.8, 2.7, 0.9);
    ctx.fillStyle = O.visor as string;
    ctx.fill();
    stroke(ctx, 0.8, hi);
    ctx.beginPath();
    const gx = d === 'E' ? hx + r - 1.9 : -1.8;
    for (let k = 0; k < (d === 'E' ? 2 : 4); k++) {
      ctx.moveTo(gx + k * 1.2, cy + 4.9);
      ctx.lineTo(gx + k * 1.2, cy + 6.6);
    }
    stroke(ctx, 0.5, lo);
  }
  ctx.restore();
  helmetPath(ctx, d, hx);
  stroke(ctx, PAWN.outlineWidth);
  // Гребень и полоса цвета ранга по центру шлема.
  ctx.beginPath();
  if (d === 'E') {
    ctx.moveTo(hx - 3.5, cy - r + 1.2);
    ctx.quadraticCurveTo(hx + 1, cy - r - 0.4, hx + 4.6, cy - r + 2.2);
  } else {
    ctx.moveTo(0, cy - r + 0.2);
    ctx.lineTo(0, d === 'N' ? cy + 2 : cy - 3);
  }
  stroke(ctx, 1.6, trim);
  ctx.beginPath();
  ctx.arc(d === 'E' ? hx : 0, cy - 0.5, r - 1.6, Math.PI * 1.12, Math.PI * 1.45);
  stroke(ctx, 0.9, hi);
  // Наушники.
  const ears = d === 'E' ? [hx - 1.2] : d === 'S' ? [-r + 0.9, r - 0.9] : [-r + 1, r - 1];
  for (const ex of ears) {
    ctx.beginPath();
    ctx.arc(ex, cy + 1.6, d === 'E' ? 2.1 : 1.25, 0, Math.PI * 2);
    fillStroke(ctx, lo, PAWN.outlineWidth * 0.8);
  }
  if (d === 'N') return;
  // Блик на визоре.
  ctx.beginPath();
  if (d === 'E') {
    ctx.moveTo(hx + 2.4, cy - 1.6);
    ctx.lineTo(hx + 5, cy - 1.6);
  } else {
    ctx.moveTo(-r + 3, cy - 1.4);
    ctx.lineTo(-r + 6, cy - 1.4);
  }
  stroke(ctx, 0.8, O.shine as string);
  // Огоньки глаз в визоре: у OTA.ALPHA — два голубых, у OTA.KING и главы — один.
  if (O.eye) {
    const eyes = d === 'E' ? [hx + r - 0.2] : O.eyes === 2 ? [-2.9, 2.9] : [2.8];
    ctx.save();
    ctx.fillStyle = O.eye as string;
    const a0 = ctx.globalAlpha;
    for (const ex of eyes) {
      ctx.globalAlpha = a0 * 0.35;
      ctx.beginPath();
      ctx.arc(ex, cy - 0.9, 2, 0, Math.PI * 2);
      ctx.fill();
      ctx.globalAlpha = a0;
      ctx.beginPath();
      ctx.arc(ex, cy - 0.9, 0.95, 0, Math.PI * 2);
      ctx.fill();
    }
    ctx.restore();
  }
}

/**
 * Детали профессий поверх туловища: красный крест на халате медика, фартук повара, сумка курьера,
 * светоотражающие полосы уборщика, заплаты отброса, повязка медика сопротивления.
 */
function professionBody(ctx: Ctx, d: PawnDir, O: Outfit): void {
  const B = PAWN.body;
  const side = d === 'E';
  if (O.apron && d !== 'N') {
    ctx.beginPath();
    if (side) roundRect(ctx, 1.2, B.top + 4, 6, 10, 1.6);
    else roundRect(ctx, -5, B.top + 3.6, 10, 11.2, 2);
    fillStroke(ctx, O.apron as string);
  }
  if (O.cross && d === 'S') {
    ctx.fillStyle = O.cross as string;
    ctx.fillRect(-4.8, B.top + 3.2, 3.6, 1.2);
    ctx.fillRect(-3.6, B.top + 2, 1.2, 3.6);
  }
  if (O.hivis) {
    ctx.beginPath();
    ctx.moveTo(side ? -2 : -7, 3);
    ctx.lineTo(side ? 6.6 : 7, 3);
    ctx.moveTo(side ? -2.4 : -7.6, 7);
    ctx.lineTo(side ? 7 : 7.6, 7);
    stroke(ctx, 1.4, O.hivis as string);
  }
  if (O.patch && d !== 'N') {
    ctx.beginPath();
    ctx.rect(side ? 2 : -4.8, 2, 3, 2.6);
    ctx.rect(side ? 0 : 2.2, 8, 2.6, 2.4);
    fillStroke(ctx, O.patch as string, 0.6);
  }
  if (O.bag) {
    // Ремень через плечо и сумка на бедре.
    ctx.beginPath();
    ctx.moveTo(side ? -2 : -5.5, B.top + 0.6);
    ctx.lineTo(side ? 3 : 5.5, 8);
    stroke(ctx, 1.2, O.bag as string);
    ctx.beginPath();
    if (side) roundRect(ctx, -6.2, 6.4, 5, 5, 1.2);
    else roundRect(ctx, 3.4, 6.6, 5.4, 4.6, 1.2);
    fillStroke(ctx, O.bag as string, PAWN.outlineWidth * 0.8);
  }
  if (O.bandolier && d !== 'N') {
    // Патронташ подрывника: ремень через грудь с гранатами.
    ctx.beginPath();
    ctx.moveTo(side ? -3 : -6, B.top + 0.8);
    ctx.lineTo(side ? 4 : 6, 9);
    stroke(ctx, 2.2, O.bandolier as string);
    const n = side ? 2 : 3;
    for (let k = 0; k < n; k++) {
      const t = (k + 1) / (n + 1);
      const gx = (side ? -3 : -6) + ((side ? 4 : 6) - (side ? -3 : -6)) * t;
      const gy = B.top + 0.8 + (9 - B.top - 0.8) * t;
      ctx.beginPath();
      ctx.arc(gx, gy, 1.5, 0, Math.PI * 2);
      fillStroke(ctx, O.nade as string, 0.6);
    }
  }
  if (O.armband && d !== 'N') {
    ctx.beginPath();
    const ax = side ? 0.2 : -PAWN.body.shoulder - 0.2;
    ctx.rect(ax - 2, B.top + 4.4, 4, 2.6);
    fillStroke(ctx, O.armband as string, 0.7);
    if (O.armbandCross) {
      ctx.fillStyle = O.armbandCross as string;
      ctx.fillRect(ax - 0.4, B.top + 4.6, 0.8, 2.2);
      ctx.fillRect(ax - 1.1, B.top + 5.3, 2.2, 0.8);
    }
  }
}

/**
 * Противогаз HYDRA (как у SAS): две круглые линзы с бликом, резиновая маска и фильтр сбоку,
 * ремни на затылке; сверху — чёрная балаклава (голова уже залита цветом маски).
 */
function respirator(ctx: Ctx, d: PawnDir, O: Outfit, hx: number): void {
  const H = PAWN.head;
  const cy = H.y;
  const rubber = O.rubber as string;
  const lens = O.lens as string;
  if (d === 'N') {
    // Затылок: ремни маски крест-накрест.
    ctx.beginPath();
    ctx.moveTo(-H.r + 1, cy - 1);
    ctx.lineTo(H.r - 1, cy + 3);
    ctx.moveTo(H.r - 1, cy - 1);
    ctx.lineTo(-H.r + 1, cy + 3);
    stroke(ctx, 1, rubber);
    return;
  }
  const side = d === 'E';
  // Резиновая маска на лице.
  ctx.beginPath();
  if (side) ctx.ellipse(hx + 3.2, cy + 1, 4.6, 5.2, 0, 0, Math.PI * 2);
  else ctx.ellipse(0, cy + 1.2, 6.2, 5.6, 0, 0, Math.PI * 2);
  fillStroke(ctx, rubber, PAWN.outlineWidth * 0.8);
  // Линзы.
  const lensAt = side ? [[hx + 4.4, cy - 0.6]] : [[-2.8, cy - 0.4], [2.8, cy - 0.4]];
  for (const [lx, ly] of lensAt) {
    ctx.beginPath();
    ctx.arc(lx, ly, side ? 2 : 2.3, 0, Math.PI * 2);
    fillStroke(ctx, lens, 0.9);
    ctx.fillStyle = 'rgba(255,255,255,0.45)';
    ctx.fillRect(lx - 1.1, ly - 1.3, 0.9, 0.9);
  }
  // Фильтр: спереди-сбоку (S) или впереди (профиль).
  ctx.beginPath();
  if (side) ctx.ellipse(hx + 7.2, cy + 3.6, 2, 2.4, 0, 0, Math.PI * 2);
  else ctx.ellipse(3.8, cy + 4.6, 2.4, 2, 0, 0, Math.PI * 2);
  fillStroke(ctx, O.filter as string, 0.8);
  ctx.beginPath();
  if (side) ctx.moveTo(hx + 6.2, cy + 3.6), ctx.lineTo(hx + 8.2, cy + 3.6);
  else ctx.moveTo(2.6, cy + 4.6), ctx.lineTo(5, cy + 4.6);
  stroke(ctx, 0.5, 'rgba(0,0,0,0.6)');
}

/** Берет главы восстания (набок). */
function beret(ctx: Ctx, d: PawnDir, color: string, hx: number): void {
  const H = PAWN.head;
  const cy = H.y;
  const r = H.r;
  const cx = d === 'E' ? hx - 0.6 : 0;
  ctx.beginPath();
  ctx.ellipse(cx - (d === 'S' ? 1.4 : 0), cy - r + 1.6, r + 1.6, 3.6, d === 'S' ? -0.18 : 0, 0, Math.PI * 2);
  fillStroke(ctx, color, PAWN.outlineWidth);
  ctx.beginPath();
  ctx.moveTo(cx - r + 0.4, cy - r + 3.6);
  ctx.lineTo(cx + r - 0.6, cy - r + 3.6);
  stroke(ctx, 1.1, tint(color, -0.35));
  if (d === 'S') {
    ctx.fillStyle = PAWN.gear.gold;
    ctx.beginPath();
    ctx.arc(cx + 2.4, cy - r + 1.8, 0.9, 0, Math.PI * 2);
    ctx.fill();
  }
}

/** Поварской колпак. */
function chefHat(ctx: Ctx, d: PawnDir, color: string, hx: number): void {
  const H = PAWN.head;
  const cy = H.y;
  const cx = d === 'E' ? hx - 0.5 : 0;
  ctx.beginPath();
  ctx.moveTo(cx - 5.2, cy - 4.2);
  ctx.lineTo(cx - 5.4, cy - 7.4);
  ctx.bezierCurveTo(cx - 8.4, cy - 9.6, cx - 5.6, cy - 14.4, cx - 2.4, cy - 12.8);
  ctx.bezierCurveTo(cx - 1.2, cy - 15.6, cx + 2.8, cy - 15.2, cx + 3, cy - 12.6);
  ctx.bezierCurveTo(cx + 6.4, cy - 13.8, cx + 8.2, cy - 9.2, cx + 5.4, cy - 7.4);
  ctx.lineTo(cx + 5.2, cy - 4.2);
  ctx.closePath();
  fillStroke(ctx, color, PAWN.outlineWidth);
  ctx.beginPath();
  ctx.moveTo(cx - 5.3, cy - 6.4);
  ctx.lineTo(cx + 5.3, cy - 6.4);
  stroke(ctx, 0.7, tint(color, -0.25));
}

/** Защитные очки пиротехника. */
function goggles(ctx: Ctx, d: PawnDir, lens: string, hx: number): void {
  const E = PAWN.eye;
  ctx.beginPath();
  if (d === 'E') ctx.moveTo(hx - PAWN.head.r, E.y - 0.6), ctx.lineTo(hx + PAWN.head.r - 3.6, E.y - 0.6);
  else ctx.moveTo(-PAWN.head.r, E.y - 0.6), ctx.lineTo(PAWN.head.r, E.y - 0.6);
  stroke(ctx, 1.1, '#2a2622');
  const lenses = d === 'E' ? [hx + PAWN.head.r - 2.4] : [-E.dx, E.dx];
  for (const lx of lenses) {
    ctx.beginPath();
    ctx.arc(lx, E.y - 0.2, 1.9, 0, Math.PI * 2);
    fillStroke(ctx, lens, 0.9);
    ctx.beginPath();
    ctx.arc(lx - 0.6, E.y - 0.8, 0.5, 0, Math.PI * 2);
    ctx.fillStyle = 'rgba(255,255,255,0.8)';
    ctx.fill();
  }
}

/** Санитар: синтет в длинном плаще, бледная лысая голова, маска с одним зелёным глазом, бак за спиной. */
function cremator(ctx: Ctx, d: PawnDir, O: Outfit): void {
  const B = PAWN.body;
  const side = d === 'E';
  if (d === 'N' || side) {
    ctx.beginPath();
    roundRect(ctx, side ? -9 : -4.4, B.top + 1.5, side ? 4.6 : 8.8, 9, 2.2);
    fillStroke(ctx, O.tank as string, PAWN.outlineWidth);
  }
  bodyPath(ctx, d);
  ctx.fillStyle = O.coat as string;
  ctx.fill();
  ctx.save();
  ctx.clip();
  ctx.fillStyle = PAWN.shade;
  ctx.fillRect(side ? -20 : 2.5, -20, side ? 18 : 20, 40);
  if (d === 'S') {
    ctx.beginPath();
    ctx.moveTo(0, B.top);
    ctx.lineTo(0, B.bottom);
    stroke(ctx, PAWN.seamWidth);
  }
  ctx.restore();
  bodyPath(ctx, d);
  stroke(ctx, PAWN.outlineWidth);
  const hx = side ? PAWN.head.sideShift : 0;
  headPath(ctx, d, hx);
  ctx.fillStyle = O.skin as string;
  ctx.fill();
  ctx.save();
  headPath(ctx, d, hx);
  ctx.clip();
  if (d !== 'N') {
    ctx.fillStyle = O.mask as string;
    if (side) ctx.fillRect(hx - 1, PAWN.head.y - 1, 20, 20);
    else ctx.fillRect(-20, PAWN.head.y - 1, 40, 20);
  }
  ctx.restore();
  headPath(ctx, d, hx);
  stroke(ctx, PAWN.outlineWidth);
  if (d !== 'N') {
    const ex = side ? hx + PAWN.head.r - 2.4 : 0;
    ctx.beginPath();
    ctx.arc(ex, PAWN.head.y - 3.4, 1.7, 0, Math.PI * 2);
    ctx.fillStyle = O.eye as string;
    ctx.fill();
    stroke(ctx, 0.8);
  }
}

/** Тень под ногами пешки. */
export function drawPawnShadow(ctx: Ctx, x: number, y: number, s: number): void {
  const S = PAWN.shadow;
  ctx.fillStyle = S.color;
  ctx.beginPath();
  ctx.ellipse(x, y + S.y * s, S.rx * s, S.ry * s, 0, 0, Math.PI * 2);
  ctx.fill();
}
